import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Input from '@mui/joy/Input';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import ListItemContent from '@mui/joy/ListItemContent';
import ListSubheader from '@mui/joy/ListSubheader';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import IconButton from '@mui/joy/IconButton';
import CircularProgress from '@mui/joy/CircularProgress';
import Tooltip from '@mui/joy/Tooltip';
import Alert from '@mui/joy/Alert';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import Button from '@mui/joy/Button';
import SearchIcon from '@mui/icons-material/Search';
import RefreshIcon from '@mui/icons-material/Refresh';
import FunctionsIcon from '@mui/icons-material/Functions';
import GridOnIcon from '@mui/icons-material/GridOn';

import { ODb, TableInfo, TableData, TableRowData } from '../db';
import Spreadsheet from './Spreadsheet';

function baseName(path: string): string {
    const parts = path.split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

function tableLabel(t: TableInfo): string {
    if (t.Name !== '') return t.Name;
    if (t.Heading !== '') return t.Heading;
    return `Table ${t.Id + 1}`;
}

// Every word of the search has to turn up somewhere in the table's name, file
// or heading, which is what makes a search like "budget org food" work.
function matches(t: TableInfo, terms: string[]): boolean {
    if (terms.length === 0) return true;
    const hay = `${t.Name} ${t.Heading} ${t.Filename} ${baseName(t.Filename)} table ${t.Id + 1}`.toLowerCase();
    return terms.every(term => hay.indexOf(term) >= 0);
}

export default function Tables() {
    const [tables, setTables] = React.useState<TableInfo[]>([]);
    const [loadingList, setLoadingList] = React.useState(true);
    const [filter, setFilter] = React.useState('');
    const [selected, setSelected] = React.useState<TableInfo | null>(null);
    const [table, setTable] = React.useState<TableData | null>(null);
    const [loadingTable, setLoadingTable] = React.useState(false);
    const [saving, setSaving] = React.useState(false);
    const [message, setMessage] = React.useState('');
    const [dirty, setDirty] = React.useState(false);
    const [pending, setPending] = React.useState<TableInfo | null>(null);

    const loadList = React.useCallback(async () => {
        setLoadingList(true);
        const res = await ODb.getTables();
        setTables(res && res.Tables ? res.Tables : []);
        setLoadingList(false);
    }, []);

    React.useEffect(() => {
        loadList();
    }, [loadList]);

    const openTable = React.useCallback(async (info: TableInfo) => {
        setSelected(info);
        setLoadingTable(true);
        setMessage('');
        const res = await ODb.getTable(info.Filename, info.Id);
        if (res && res.Ok && res.Table) {
            setTable(res.Table);
        } else {
            setTable(null);
            setMessage(res && res.Msg ? res.Msg : 'Could not load that table');
        }
        setLoadingTable(false);
    }, []);

    function chooseTable(info: TableInfo) {
        if (dirty && selected !== null && (selected.Filename !== info.Filename || selected.Id !== info.Id)) {
            setPending(info);
            return;
        }
        openTable(info);
    }

    async function onSave(rows: TableRowData[], formulas: string[], name: string, evaluate: boolean) {
        if (!selected) return;
        setSaving(true);
        setMessage('');
        const res = await ODb.saveTable({
            Filename: selected.Filename,
            Id: selected.Id,
            Data: rows,
            Formulas: formulas.filter(f => f.trim() !== ''),
            Name: name,
            SetName: true,
            Eval: evaluate,
        });
        if (res && res.Table) {
            setTable(res.Table);
            setSelected({ ...selected, Name: res.Table.Name });
            setDirty(false);
        }
        if (res && !res.Ok) {
            setMessage(res.Msg || 'Save failed');
        }
        setSaving(false);
        loadList();
    }

    const terms = filter.toLowerCase().split(/\s+/).filter(t => t !== '');
    const shown = tables.filter(t => matches(t, terms));
    const byFile: { file: string; tables: TableInfo[] }[] = [];
    for (const t of shown) {
        const last = byFile.length > 0 ? byFile[byFile.length - 1] : null;
        if (last !== null && last.file === t.Filename) {
            last.tables.push(t);
        } else {
            byFile.push({ file: t.Filename, tables: [t] });
        }
    }

    return (
        <Box sx={{ display: 'flex', gap: 2, flex: 1, minHeight: 0 }}>
            {/* Table list */}
            <Sheet
                variant="outlined"
                sx={{
                    width: 320,
                    flexShrink: 0,
                    borderRadius: 'sm',
                    display: 'flex',
                    flexDirection: 'column',
                    minHeight: 0,
                }}
            >
                <Box sx={{ p: 1, display: 'flex', gap: 1, alignItems: 'center' }}>
                    <Input
                        size="sm"
                        placeholder="Search tables"
                        value={filter}
                        onChange={e => setFilter(e.target.value)}
                        startDecorator={<SearchIcon />}
                        sx={{ flex: 1 }}
                    />
                    <Tooltip title="Reload the table list" size="sm">
                        <IconButton size="sm" variant="outlined" color="neutral" onClick={loadList}>
                            <RefreshIcon />
                        </IconButton>
                    </Tooltip>
                </Box>
                <Box sx={{ px: 1, pb: 0.5 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {loadingList ? 'Loading…' : `${shown.length} of ${tables.length} tables`}
                    </Typography>
                </Box>
                <Box sx={{ overflow: 'auto', flex: 1, minHeight: 0 }}>
                    {loadingList && <Box sx={{ p: 2, textAlign: 'center' }}><CircularProgress size="sm" /></Box>}
                    {!loadingList && shown.length === 0 && (
                        <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>
                            No tables match that search.
                        </Typography>
                    )}
                    <List size="sm" sx={{ '--ListItem-radius': '6px' }}>
                        {byFile.map(group => (
                            <ListItem nested key={group.file}>
                                {/* Orange, so the file a run of tables came out
                                    of is told apart at a glance from the tables
                                    themselves. Joy's warning tokens run brown in
                                    the light scheme, so the two tones are given
                                    here and picked by the scheme in play. */}
                                <ListSubheader
                                    sticky
                                    sx={{
                                        fontWeight: 'lg',
                                        color: '#c2410c',
                                        '[data-joy-color-scheme="dark"] &': { color: '#fb923c' },
                                    }}
                                >
                                    <Tooltip title={group.file} size="sm" placement="top">
                                        <span>{baseName(group.file)}</span>
                                    </Tooltip>
                                </ListSubheader>
                                <List size="sm">
                                    {group.tables.map(t => (
                                        <ListItem key={`${t.Filename}:${t.Id}`}>
                                            <ListItemButton
                                                selected={selected !== null && selected.Filename === t.Filename && selected.Id === t.Id}
                                                onClick={() => chooseTable(t)}
                                            >
                                                <ListItemContent>
                                                    <Typography level="body-sm" sx={{ fontWeight: t.Name !== '' ? 600 : 400 }}>
                                                        {tableLabel(t)}
                                                    </Typography>
                                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                                        {t.Heading !== '' ? t.Heading : 'before the first heading'} · line {t.Line + 1}
                                                    </Typography>
                                                    <Box sx={{ display: 'flex', gap: 0.5, mt: 0.25 }}>
                                                        <Chip size="sm" variant="soft" color="neutral">{t.Rows}×{t.Cols}</Chip>
                                                        {t.Formulas > 0 && (
                                                            <Chip size="sm" variant="soft" color="warning" startDecorator={<FunctionsIcon sx={{ fontSize: 12 }} />}>
                                                                {t.Formulas}
                                                            </Chip>
                                                        )}
                                                    </Box>
                                                </ListItemContent>
                                            </ListItemButton>
                                        </ListItem>
                                    ))}
                                </List>
                            </ListItem>
                        ))}
                    </List>
                </Box>
            </Sheet>

            {/* Editor */}
            <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: 1, minHeight: 0 }}>
                {selected === null && (
                    <Sheet variant="soft" sx={{ flex: 1, borderRadius: 'sm', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Box sx={{ textAlign: 'center', color: 'text.tertiary' }}>
                            <GridOnIcon sx={{ fontSize: 48, opacity: 0.4 }} />
                            <Typography level="body-sm">Pick a table to open it as a spreadsheet.</Typography>
                        </Box>
                    </Sheet>
                )}
                {selected !== null && (
                    <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1, minWidth: 0 }}>
                        <Typography level="title-md" sx={{ flexShrink: 0 }}>{tableLabel(selected)}</Typography>
                        {/* A file path has nothing to wrap on, so the full one
                            lives in the tooltip rather than widening the page. */}
                        <Tooltip title={selected.Filename} size="sm" placement="bottom-start">
                            <Typography
                                level="body-xs"
                                sx={{ color: 'text.tertiary', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
                            >
                                {baseName(selected.Filename)}{selected.Heading !== '' ? ` · ${selected.Heading}` : ''}
                            </Typography>
                        </Tooltip>
                    </Box>
                )}
                {message !== '' && (
                    <Alert size="sm" color="danger" variant="soft">{message}</Alert>
                )}
                {loadingTable && <Box sx={{ p: 2 }}><CircularProgress size="sm" /></Box>}
                {!loadingTable && table !== null && (
                    <Spreadsheet
                        key={`${table.Filename}:${table.Id}`}
                        table={table}
                        saving={saving}
                        message={''}
                        onSave={onSave}
                        onDirtyChange={setDirty}
                    />
                )}
            </Box>

            {/* Leaving a table with edits that were never written out */}
            <Modal open={pending !== null} onClose={() => setPending(null)}>
                <ModalDialog>
                    <Typography level="title-md">Discard unsaved changes?</Typography>
                    <Typography level="body-sm">
                        The table you are editing has changes that have not been written to its org file.
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 1 }}>
                        <Button size="sm" variant="plain" color="neutral" onClick={() => setPending(null)}>Keep editing</Button>
                        <Button
                            size="sm"
                            color="danger"
                            onClick={() => {
                                const next = pending;
                                setPending(null);
                                setDirty(false);
                                if (next) openTable(next);
                            }}
                        >
                            Discard
                        </Button>
                    </Box>
                </ModalDialog>
            </Modal>
        </Box>
    );
}
