function pad2(num: number): string {
    return String(num).padStart(2, '0');
}

// A row of an org table. Kind is "data" for a normal row and "sep" for a
// horizontal rule. Advanced carries the org special row marker ("!", "^", "_",
// "$", "/") when the row has one.
export type TableRowData = {
    Kind: string;
    Advanced?: string;
    Cells: string[];
};

// Summary of one table, as listed by /tables.
export type TableInfo = {
    Id: number;
    Filename: string;
    Name: string;
    Heading: string;
    Olp: string[];
    Line: number;
    Rows: number;
    Cols: number;
    Formulas: number;
};

// A table and everything needed to edit it.
export type TableData = TableInfo & {
    EndLine: number;
    Data: TableRowData[];
    FormulaList: string[];
    // Keyed "row,col", both zero based, indexing into Data.
    CellFormulas: Record<string, string>;
    ColNames: Record<string, number> | null;
    Params: Record<string, string> | null;
    Indent: string;
};

export type TableListResult = { Ok: boolean; Msg: string; Tables: TableInfo[] };
export type TableResult = { Ok: boolean; Msg: string; Table: TableData | null };

export type TableEdit = {
    Filename: string;
    Id: number;
    Data: TableRowData[];
    Formulas: string[];
    Name?: string;
    SetName?: boolean;
    Eval?: boolean;
};

// ---------------------------------------------------------------------------
// Links: who points at whom across the org files
// ---------------------------------------------------------------------------

// One end of a link. A file level end - a link that points at a whole file, or
// one written before the first heading - leaves Hash, Headline and Olp empty.
export type LinkEnd = {
    Filename: string;
    Hash: string;
    Headline: string;
    Olp: string[] | null;
    Level: number;
    Line: number;
};

export type OrgLink = {
    From: LinkEnd;
    To: LinkEnd;
    Raw: string;
    Desc: string;
    // id, custom-id, file, heading, fuzzy, external or unresolved
    Kind: string;
    Broken: boolean;
};

export type Backlinks = {
    Ok: boolean;
    Msg: string;
    Filename: string;
    In: OrgLink[] | null;       // written elsewhere, pointing here
    Out: OrgLink[] | null;      // written here, pointing elsewhere
    Internal: OrgLink[] | null; // written here, pointing back into here
};

export type LinkGraphNode = {
    Id: string;       // "file:<path>" or "node:<hash>"
    Kind: string;     // file or heading
    Label: string;
    Filename: string;
    Hash: string;
    Olp: string[] | null;
    Level: number;
    In: number;
    Out: number;
    Center: boolean;
    Distance: number;
};

// Two nodes that link at each other come back as one edge with Both set.
// Count is how many links run From -> To, Back how many run To -> From.
export type LinkGraphEdge = {
    From: string;
    To: string;
    Count: number;
    Back: number;
    Both: boolean;
    Broken: boolean;
};

export type LinkGraphResult = {
    Ok: boolean;
    Msg: string;
    Center: string;
    Nodes: LinkGraphNode[] | null;
    Edges: LinkGraphEdge[] | null;
};

export type LinkFileStat = {
    Filename: string;
    In: number;
    Out: number;
    Internal: number;
    Broken: number;
};

export type LinkStatsResult = { Ok: boolean; Msg: string; Files: LinkFileStat[] | null };

// ---------------------------------------------------------------------------
// Kanban boards
// ---------------------------------------------------------------------------

// One column of a board. Value is what puts a card here, read against whatever
// the board groups by: the grouping property's value, the tag name, or the todo
// keyword.
export type KanbanColumn = {
    value: string;
    title: string;
    color: string;
    limit: number;
    collapsed: boolean;
};

// A saved board: where its cards come from, what splits them into columns, and
// how they are drawn. It holds no cards - every one of them is worked out from
// the query each time the board is opened.
export type KanbanBoard = {
    name: string;
    storedQuery: string;
    query: string;
    includeArchived: boolean;
    groupBy: 'property' | 'tag' | 'status';
    groupKey: string;
    columns: KanbanColumn[];
    showUnset: boolean;
    unsetTitle: string;
    colorBy: 'none' | 'property' | 'tag' | 'status' | 'priority';
    colorKey: string;
    colors: Record<string, string>;
    badges: string[];
    backShows: 'body' | 'properties' | 'both';
    sort: 'headline' | 'priority' | 'deadline' | 'scheduled' | 'file' | 'manual';
    orderKey: string;
};

