// One stretch of a transcription. Start and End are seconds into the recording.
export type VoiceSegment = {
    id: number;
    start: number;
    end: number;
    text: string;
    speaker?: string;
};

// A recording the server is holding. The id is the file's own name.
export type VoiceRecording = {
    id: string;
    bytes: number;
    seconds: number;
    created: string;
    mime: string;
};

// What the server can do about voice right now, asked before anything is
// recorded so that "whisper is not running" is said before three minutes of
// audio rather than after.
export type VoiceConfig = {
    Ok: boolean;
    Msg: string;
    ready: boolean;
    url: string;
    // Whether orgs is the one running whisper, and what its supervisor is
    // doing: off, starting, ready, adopted or failed. Shown rather than
    // guessed at from ready, because "still loading a model" and "nothing
    // installed" are both not-ready and want very different words.
    managed: boolean;
    state: string;
    log: string[] | null;
    model: string;
    models: string[];
    language: string;
    maxMb: number;
    tags: string[];
    target: { Filename: string; Id: string; Type: string; Lvl: number };
};

export type VoiceTranscription = {
    Ok: boolean;
    Msg: string;
    text: string;
    language: string;
    duration: number;
    model: string;
    segments: VoiceSegment[] | null;
};

