    // A multipart POST, for the one thing that is a file rather than json.
    // Content-Type is deliberately not set: the browser writes it, boundary
    // and all, and setting it by hand produces a body nothing can parse.
    public static async doPostForm<T>(url: any, form: FormData, retry: boolean = false): Promise<T> {
        const headers: Headers = new Headers();
        headers.set('Accept', 'application/json');
        const token = Auth.get().getToken();
        if (token) {
            headers.set('Authorization', 'Bearer ' + token);
        }
        if (url instanceof String) {
            url = new URL(Sets.orgsConnection + url);
        }
        try {
            const res = await window.fetch(new Request(url, { method: 'POST', headers, body: form }));
            if (res.status === 401 && !retry) {
                Auth.get().logout();
                await Auth.get().awaitLogin();
                return await this.doPostForm<T>(url, form, true);
            }
            return res.json() as T;
        } catch (error: any) {
            console.error(error.message);
        }
        return [] as T;
    }

    // The bytes of something the api is holding, as a Blob. A media element
    // cannot send an Authorization header, so audio is fetched here and played
    // from an object url rather than pointed at the endpoint.
    public static async doGetBlob(url: any, retry: boolean = false): Promise<Blob | null> {
        const headers: Headers = new Headers();
        const token = Auth.get().getToken();
        if (token) {
            headers.set('Authorization', 'Bearer ' + token);
        }
        if (url instanceof String) {
            url = new URL(Sets.orgsConnection + url);
        }
        try {
            const res = await window.fetch(new Request(url, { method: 'GET', headers }));
            if (res.status === 401 && !retry) {
                Auth.get().logout();
                await Auth.get().awaitLogin();
                return await this.doGetBlob(url, true);
            }
            if (!res.ok) return null;
            return await res.blob();
        } catch (error: any) {
            console.error(error.message);
        }
        return null;
    }

