// The Gantt Chart tab.
//
// One schedule, four ways of drawing it, and - for three of them - one way of
// changing it.
//
//   Mermaid  the diagram mermaid makes of /file/mermaid's source. Read only:
//            the source has no idea which heading a bar is.
//   React    worg's own svg chart. Drag to move, drag the end to re-estimate,
//            drag the handle to another bar to make it wait on it, drag a name
//            to reorder the lane.
//   Vis      vis-timeline. A real timeline: scroll and zoom over the calendar,
//            collapsible lanes, the library's own drag handles.
//   Google   Google Charts. Draws the dependency arrows and the critical path,
//            which nothing else here can; cannot be dragged at all.
//
// The three editable ones are drawn from /gantt/tasks, which answers with
// headings that know their own hash. Every edit is an ordinary org write to
// that heading, and the chart is refetched afterwards rather than updated in
// place - so what is on screen is what is in the file, and a write that failed
// cannot leave a bar sitting somewhere it is not.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Button from '@mui/joy/Button';
import CircularProgress from '@mui/joy/CircularProgress';
import FormLabel from '@mui/joy/FormLabel';
import FormControl from '@mui/joy/FormControl';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import Input from '@mui/joy/Input';
import Checkbox from '@mui/joy/Checkbox';
import Divider from '@mui/joy/Divider';
import SaveIcon from '@mui/icons-material/Save';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import BarChartIcon from '@mui/icons-material/BarChart';
import TimelineIcon from '@mui/icons-material/Timeline';
import TableChartIcon from '@mui/icons-material/TableChart';
import ZoomInIcon from '@mui/icons-material/ZoomIn';
import ZoomOutIcon from '@mui/icons-material/ZoomOut';
import FitScreenIcon from '@mui/icons-material/FitScreen';
import AddIcon from '@mui/icons-material/Add';
import UndoIcon from '@mui/icons-material/Undo';
import RefreshIcon from '@mui/icons-material/Refresh';
import PaletteIcon from '@mui/icons-material/Palette';
import mermaid from 'mermaid';
import { ODb } from '../db';
import {
    parseGantt, ganttFromTasks, GanttModel, GanttTask, GanttServerTask,
    dayKey, nextWorkingDay,
} from '../gantt';
import {
    GanttOp, UndoStack, startOp, effortOp, sectionOp, reorderOps,
    dependencyOp, deleteOp, addOp,
} from '../ganttops';
import { ColorMode, COLOR_MODES, buildScheme } from '../ganttcolor';
import { useColorScheme } from '@mui/joy/styles';
import { GanttRenderer } from '../settings';
import { useSetting } from '../useSettings';
import {
    paletteFor, GanttPalette, paintBarGradients, paintGround, paintType,
    contrastText, legibleOn, veilOn, bandOn, shade, FONT_UI, TYPE,
} from '../ganttstyle';
import ReactGantt from './ReactGantt';
import VisGantt from './VisGantt';
import GoogleGantt from './GoogleGantt';
import GanttInspector from './GanttInspector';

interface StoredQuery {
    name: string;
    query: string;
}

type ColorKeys = keyof GanttPalette;

const COLOR_KEYS: ColorKeys[] = [
    'background', 'taskDefault', 'taskActive', 'taskDone', 'taskCrit', 'sectionAlt', 'text',
];

const colorLabels: Record<ColorKeys, string> = {
    background: 'Background',
    taskDefault: 'Default Task',
    taskActive: 'Active Task',
    taskDone: 'Done Task',
    taskCrit: 'Critical Task',
    sectionAlt: 'Alternate Section',
    text: 'Text',
};

// The org files are written by us and reread by the server's file watcher, so a
// chart refetched the instant a write returns can still be the old one. Asked
// twice: once for the usual case and once for a watcher having a slow moment.
const REREAD_MS = [250, 1200];

function ColorInput({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
    return (
        <FormControl size="sm" sx={{ minWidth: 0 }}>
            <FormLabel sx={{ fontSize: '11px', mb: 0.25 }}>{label}</FormLabel>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                <input
                    type="color"
                    value={value}
                    onChange={e => onChange(e.target.value)}
                    style={{ width: 28, height: 28, border: 'none', padding: 0, cursor: 'pointer', background: 'none' }}
                />
                <Typography level="body-xs" sx={{ fontFamily: 'monospace', color: 'text.secondary' }}>
                    {value}
                </Typography>
            </Box>
        </FormControl>
    );
}

// Several writes that belong to one gesture are one press of undo. Reverting
// runs them backwards, because the second of them may depend on the first.
function combine(ops: GanttOp[]): GanttOp {
    if (ops.length === 1) return ops[0];
    const last = ops[ops.length - 1];
    return {
        label: last.label,
        hash: last.hash,
        read: last.read,
        after: last.after,
        apply: async () => { for (const o of ops) await o.apply(); },
        revert: async () => { for (let i = ops.length - 1; i >= 0; i--) await ops[i].revert(); },
    };
}

export default function GanttChart() {
    const [queries, setQueries] = React.useState<StoredQuery[]>([]);
    const [selectedQuery, setSelectedQuery] = React.useState<string | null>(null);
    const [mermaidSrc, setMermaidSrc] = React.useState<string>('');
    const [rows, setRows] = React.useState<GanttServerTask[] | null>(null);
    const [loading, setLoading] = React.useState(false);
    const [loadingQueries, setLoadingQueries] = React.useState(true);
    const [error, setError] = React.useState<string>('');
    const [notice, setNotice] = React.useState<string>('');
    // The chart follows the app's light or dark mode - a white slab in a dark
    // window is the thing this is here to stop. A colour the user has actually
    // edited is theirs and is left alone when the mode changes; the rest swap.
    const { mode, systemMode } = useColorScheme();
    const appMode = mode === 'system' ? systemMode : mode;
    const [colors, setColors] = React.useState<GanttPalette>(() => paletteFor(appMode));
    const touched = React.useRef<Set<ColorKeys>>(new Set());
    const [chartTitle, setChartTitle] = React.useState('Schedule');
    const [renderer, setRenderer] = useSetting('ganttRenderer');
    const [colorBy, setColorBy] = useSetting('ganttColorBy');
    const [colorProp, setColorProp] = useSetting('ganttColorProp');
    // Which lanes are shut, by name. Not stored: it is about the minute you are
    // having with the chart, not about the plan.
    const [shutLanes, setShutLanes] = React.useState<string[]>([]);
    // The rows picked up for moving. Separate from `selected`, which is the one
    // row the inspector edits: picking rows is about where they sit, not about
    // what they say.
    const [picked, setPicked] = React.useState<string[]>([]);
    const [dayWidth, setDayWidth] = React.useState(20);
    const [skipWeekends, setSkipWeekends] = React.useState(true);
    const [criticalPath, setCriticalPath] = React.useState(true);
    const [selected, setSelected] = React.useState<string>('');
    const [statuses, setStatuses] = React.useState<string[]>([]);
    const [busy, setBusy] = React.useState(false);
    const [adding, setAdding] = React.useState(false);
    const [undoDepth, setUndoDepth] = React.useState(0);

    const chartRef = React.useRef<HTMLDivElement>(null);
    const reactRef = React.useRef<HTMLDivElement>(null);
    const visRef = React.useRef<HTMLDivElement>(null);
    const googleRef = React.useRef<HTMLDivElement>(null);
    const renderIdRef = React.useRef(0);
    const undoRef = React.useRef(new UndoStack());

    const interactive = renderer !== 'mermaid';

    const setColor = React.useCallback((key: ColorKeys, value: string) => {
        touched.current.add(key);
        setColors(prev => ({ ...prev, [key]: value }));
    }, []);

    React.useEffect(() => {
        const next = paletteFor(appMode);
        setColors(prev => {
            const out = { ...prev };
            for (const k of COLOR_KEYS) {
                if (!touched.current.has(k)) out[k] = next[k];
            }
            return out;
        });
    }, [appMode]);

    React.useEffect(() => {
        ODb.getStoredQueries().then(result => {
            setQueries(result || []);
            setLoadingQueries(false);
        }).catch(() => {
            setQueries([]);
            setLoadingQueries(false);
        });
    }, []);

    const queryText = React.useCallback((): string => {
        const q = queries.find(x => x.name === selectedQuery);
        return q ? q.query : '';
    }, [queries, selectedQuery]);

    // --- the two ways of asking for a chart --------------------------------

    const fetchMermaid = React.useCallback(async (query: string) => {
        const result = await ODb.mermaid(query);
        let src = '';
        if (result && typeof result === 'object' && result.Msg) {
            const raw = result.Msg as string;
            // Extract gantt block, stopping before any HTML comment marker or tag
            const match = raw.match(/(gantt[\s\S]*?)(?=\s*<|$)/);
            if (match) src = match[1].trim();
        } else if (result && typeof result === 'object' && result.Content) {
            src = result.Content;
        } else if (typeof result === 'string') {
            src = result;
        }
        if (!src) throw new Error('No gantt data found in server response');
        const titleMatch = src.match(/title\s+(.+)/);
        if (titleMatch) setChartTitle(titleMatch[1].trim());
        setMermaidSrc(src);
    }, []);

    const fetchTasks = React.useCallback(async (query: string) => {
        const res = await ODb.ganttTasks(query);
        if (!res || res.Ok === false) throw new Error((res && res.Msg) || 'the server could not schedule that query');
        setRows(res.Tasks || []);
    }, []);

    const load = React.useCallback(async (quiet: boolean = false) => {
        const query = queryText();
        if (!query) return;
        if (!quiet) setLoading(true);
        try {
            if (renderer === 'mermaid') await fetchMermaid(query);
            else await fetchTasks(query);
            setError('');
        } catch (e: any) {
            setError(e.message || 'Failed to fetch the schedule');
        } finally {
            if (!quiet) setLoading(false);
        }
    }, [queryText, renderer, fetchMermaid, fetchTasks]);

    // Switching renderer switches which question is asked of the server, so the
    // chart is refetched rather than redrawn from whatever happens to be held.
    // `load` is read through a ref: it changes on every render, and this effect
    // is about the renderer changing, not about the callback being new.
    const loadRef = React.useRef(load);
    loadRef.current = load;
    const haveQuery = selectedQuery !== null;
    React.useEffect(() => {
        if (haveQuery) loadRef.current();
    }, [renderer, haveQuery]);

    const model: GanttModel | null = React.useMemo(() => {
        if (renderer === 'mermaid') return mermaidSrc ? parseGantt(mermaidSrc) : null;
        if (!rows) return null;
        return ganttFromTasks(rows, { excludeWeekends: skipWeekends, title: chartTitle });
    }, [renderer, mermaidSrc, rows, skipWeekends, chartTitle]);

    const tasks = model ? model.tasks : [];

    // Mermaid has four fixed task classes in its theme and no way to be told
    // about a fifth, so it is always coloured by state whatever the toolbar
    // says - and the toolbar says so rather than pretending otherwise.
    const schemeMode: ColorMode = renderer === 'mermaid' ? 'state' : (colorBy as ColorMode);
    const scheme = React.useMemo(
        () => buildScheme(tasks, schemeMode, colors, colorProp),
        [tasks, schemeMode, colors, colorProp],
    );

    const toggleLane = React.useCallback((name: string) => {
        setShutLanes(prev => (prev.indexOf(name) >= 0 ? prev.filter(n => n !== name) : [...prev, name]));
    }, []);
    const selectedTask = tasks.find(t => t.hash && t.hash === selected) || null;

    // The keywords this file allows, asked of the heading that is selected -
    // org files can each declare their own, so there is no one list to cache.
    React.useEffect(() => {
        if (!selected) return;
        let alive = true;
        ODb.validStatus(selected).then(r => {
            if (!alive || !r) return;
            setStatuses([...(r.Active || []), ...(r.Done || [])]);
        }).catch(() => { });
        return () => { alive = false; };
    }, [selected]);

    // --- writing -----------------------------------------------------------

    const reread = React.useCallback(async () => {
        for (const wait of REREAD_MS) {
            await new Promise(r => window.setTimeout(r, wait));
            await load(true);
        }
    }, [load]);

    const runOps = React.useCallback(async (ops: GanttOp[], record: boolean = true) => {
        if (ops.length === 0) return;
        setBusy(true);
        setError('');
        try {
            const op = combine(ops);
            await op.apply();
            if (record) {
                undoRef.current.push(op);
                setUndoDepth(undoRef.current.depth);
            }
            setNotice(op.label);
            await reread();
        } catch (e: any) {
            setError(e.message || 'that change could not be saved');
        } finally {
            setBusy(false);
        }
    }, [reread]);

    const undo = React.useCallback(async () => {
        setBusy(true);
        setError('');
        try {
            const label = await undoRef.current.undo(hash => tasks.find(t => t.hash === hash) || null);
            setUndoDepth(undoRef.current.depth);
            setNotice(`Undid: ${label}`);
            await reread();
        } catch (e: any) {
            setError(e.message || 'that could not be undone');
            setUndoDepth(undoRef.current.depth);
        } finally {
            setBusy(false);
        }
    }, [tasks, reread]);

    // --- the gestures the charts hand up -----------------------------------

    const onMove = React.useCallback((t: GanttTask, start: Date) => {
        // Dropped on a day the chart does not lay work on, the task starts on
        // the next one it does - which is where the bar is about to be drawn.
        runOps([startOp(t, model ? nextWorkingDay(start, model) : start)]);
    }, [runOps, model]);

    const onResize = React.useCallback((t: GanttTask, days: number) => {
        runOps([effortOp(t, days)]);
    }, [runOps]);

    const onLink = React.useCallback((waits: GanttTask, on: GanttTask) => {
        // The bar the handle was dropped on is the one that now waits. Giving
        // the other one an id, if it has none, is part of the same undo: AFTER
        // names an id, so there has to be one to name.
        const { op, ensureId } = dependencyOp(waits, on);
        runOps(ensureId ? [ensureId, op] : [op]);
    }, [runOps]);

    const onSection = React.useCallback((t: GanttTask, section: string) => {
        runOps([sectionOp(t, section)]);
    }, [runOps]);

    // Rows dropped somewhere else in the list. The lane is rebuilt with the
    // moved rows taken out and put back at the drop point, then renumbered -
    // one write per row whose number actually changed, and the whole move is
    // one undo. A row dropped into a different lane has its SECTION written
    // too, which is what makes dragging between lanes mean what it looks like.
    const onReorderRows = React.useCallback((moved: GanttTask[], lane: string, index: number) => {
        const movedIds = new Set(moved.map(m => m.id));
        const rest = tasks.filter(t => !t.mark && t.section === lane && !movedIds.has(t.id));
        const at = Math.max(0, Math.min(index, rest.length));
        const next = [...rest.slice(0, at), ...moved, ...rest.slice(at)];
        // Nothing actually moved: a grip was clicked to pick a row up and put
        // straight back down. That must write *nothing* - renumbering a lane
        // that has no orders yet changes every row in it, so without this a
        // click to select silently rewrote the whole lane.
        const current = tasks.filter(t => !t.mark && t.section === lane);
        const unmoved = next.length === current.length
            && next.every((t, i) => t.id === current[i].id);
        if (unmoved) return;

        const ops: GanttOp[] = [];
        for (const m of moved) {
            if (m.section !== lane) ops.push(sectionOp(m, lane));
        }
        ops.push(...reorderOps(next));
        if (ops.length === 0) return;
        runOps(ops);
    }, [tasks, runOps]);

    const onDelete = React.useCallback((t: GanttTask) => {
        runOps([deleteOp(t)]);
        if (selected === t.hash) setSelected('');
    }, [runOps, selected]);

    // --- adding ------------------------------------------------------------

    const [newTask, setNewTask] = React.useState({
        headline: '',
        status: 'TODO',
        start: dayKey(new Date()),
        effort: '2',
        parent: '',
    });

    const doAdd = React.useCallback(async () => {
        const parent = tasks.find(t => t.hash === newTask.parent);
        const add = {
            ParentHash: parent ? (parent.parent || parent.hash) : undefined,
            Filename: parent ? undefined : (tasks[0] ? tasks[0].filename : undefined),
            Headline: newTask.headline.trim(),
            Status: newTask.status,
            Start: newTask.start,
            DateKind: 'SCHEDULED',
            Effort: `${newTask.effort}d`,
        };
        if (!add.Headline) return;
        if (!add.ParentHash && !add.Filename) {
            setError('Nothing in the chart yet to say which file the new task belongs in');
            return;
        }
        setAdding(false);
        // The new heading has no hash until the server has reread the file, so
        // undo finds it by what it was called rather than remembering one.
        const find = async (): Promise<string | null> => {
            const q = queryText();
            const res = await ODb.ganttTasks(q);
            const hit = (res.Tasks || []).filter(t => t.Headline === add.Headline);
            return hit.length > 0 ? hit[hit.length - 1].Hash : null;
        };
        await runOps([addOp(add, find)]);
    }, [newTask, tasks, queryText, runOps]);

    // --- mermaid -----------------------------------------------------------

    React.useEffect(() => {
        if (renderer !== 'mermaid') return;
        if (!mermaidSrc || !chartRef.current) return;

        const currentId = ++renderIdRef.current;
        chartRef.current.innerHTML = '';
        const src = mermaidSrc.replace(/title\s+.+/, `title ${chartTitle}`);
        const ink = legibleOn(colors.text, colors.background);

        mermaid.initialize({
            startOnLoad: false,
            // A query over a real org database makes a gantt far past mermaid's
            // own 50k character ceiling, which it refuses rather than truncates.
            maxTextSize: 2000000,
            theme: 'base',
            fontFamily: FONT_UI,
            themeVariables: {
                fontFamily: FONT_UI,
                fontSize: `${TYPE.task.size}px`,
                primaryColor: colors.taskDefault,
                primaryTextColor: ink,
                primaryBorderColor: colors.taskDefault,
                secondaryColor: colors.sectionAlt,
                tertiaryColor: colors.sectionAlt,
                lineColor: veilOn(colors.background, 0.5),
                textColor: ink,
                mainBkg: colors.background,
                background: colors.background,
                sectionBkgColor: colors.background,
                altSectionBkgColor: colors.sectionAlt,
                gridColor: veilOn(colors.background, 0.18),
                // The days nobody works. mermaid paints these #eeeeee from its
                // own defaults, which is a light stripe across a dark chart.
                excludeBkgColor: bandOn(colors.background),
                todayLineColor: '#e74c3c',
                taskBkgColor: colors.taskDefault,
                activeTaskBkgColor: colors.taskActive,
                activeTaskBorderColor: colors.taskActive,
                doneTaskBkgColor: colors.taskDone,
                doneTaskBorderColor: colors.taskDone,
                critBkgColor: colors.taskCrit,
                critBorderColor: colors.taskCrit,
                // mermaid uses one colour for every label inside a bar, so it
                // gets the one that reads on the commonest bar; the paint pass
                // afterwards fixes up any label whose own bar disagrees.
                taskTextColor: contrastText(colors.taskDefault),
                taskTextDarkColor: contrastText(colors.taskDefault),
                taskTextLightColor: contrastText(colors.taskDefault),
                taskTextOutsideColor: ink,
                titleColor: ink,
                sectionBkgColor2: colors.sectionAlt,
            },
            gantt: {
                titleTopMargin: 25,
                barHeight: 20,
                barGap: 4,
                topPadding: 50,
                numberSectionStyles: 4,
            },
        });

        const render = async () => {
            try {
                const { svg } = await mermaid.render(`gantt-${currentId}`, src);
                if (renderIdRef.current === currentId && chartRef.current) {
                    chartRef.current.innerHTML = svg;
                    // mermaid paints flat bars from the theme it was given and
                    // has no gradient of its own, so its finished svg is
                    // repainted - the same pass the Google chart gets.
                    const bars = [colors.taskDefault, colors.taskActive, colors.taskDone, colors.taskCrit];
                    paintGround(chartRef.current, colors.background, bars);
                    paintBarGradients(chartRef.current, bars, 'mm');
                    paintType(chartRef.current, { title: 'titleText', on: colors.background, onBars: bars });
                }
            } catch (e: any) {
                if (renderIdRef.current === currentId && chartRef.current) {
                    chartRef.current.innerHTML = `<pre style="color: red; white-space: pre-wrap;">${e.message || 'Render error'}</pre>`;
                }
            }
        };
        render();
    }, [renderer, mermaidSrc, colors, chartTitle]);

    const fitZoom = React.useCallback(() => {
        if (!model || !reactRef.current) return;
        const avail = reactRef.current.clientWidth - 250;
        if (avail < 100) return;
        const days = Math.max(1, Math.round((model.end.getTime() - model.start.getTime()) / 86400000));
        setDayWidth(Math.max(2, Math.min(60, avail / days)));
    }, [model]);

    const activeBox = (): HTMLDivElement | null => {
        switch (renderer) {
            case 'react': return reactRef.current;
            case 'vis': return visRef.current;
            case 'google': return googleRef.current;
        }
        return chartRef.current;
    };

    const haveChart = renderer === 'mermaid' ? !!mermaidSrc : !!model;

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {/* Query and toolbar */}
            <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 2 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                    <Typography level="title-sm" sx={{ minWidth: 'fit-content' }}>Query:</Typography>
                    {loadingQueries ? (
                        <CircularProgress size="sm" />
                    ) : queries.length === 0 ? (
                        <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                            No saved queries. Add some in the Saved Queries tab first.
                        </Typography>
                    ) : (
                        <>
                            <Select
                                size="sm"
                                placeholder="Select a saved query"
                                value={selectedQuery}
                                onChange={(_, value) => setSelectedQuery(value)}
                                sx={{ minWidth: 250 }}
                            >
                                {queries.map(q => (
                                    <Option key={q.name} value={q.name}>
                                        {q.name}
                                        <Typography level="body-xs" sx={{ ml: 1, color: 'text.tertiary', fontFamily: 'monospace' }}>
                                            {q.query.length > 40 ? q.query.slice(0, 40) + '...' : q.query}
                                        </Typography>
                                    </Option>
                                ))}
                            </Select>
                            <Button
                                size="sm"
                                onClick={() => load()}
                                disabled={selectedQuery === null || loading}
                                loading={loading}
                            >
                                Generate
                            </Button>
                        </>
                    )}

                    <Box sx={{ ml: 'auto', display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                        {interactive && (
                            <>
                                <Tooltip size="sm" title="Add a task to this plan">
                                    <IconButton size="sm" variant="outlined" disabled={!haveChart || busy}
                                        onClick={() => setAdding(true)}>
                                        <AddIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip size="sm" title={undoDepth > 0 ? `Undo: ${undoRef.current.peek()?.label}` : 'Nothing to undo'}>
                                    <span>
                                        <IconButton size="sm" variant="outlined" disabled={undoDepth === 0 || busy} onClick={undo}>
                                            <UndoIcon />
                                        </IconButton>
                                    </span>
                                </Tooltip>
                                <Tooltip size="sm" title="Reread the plan from the server">
                                    <IconButton size="sm" variant="outlined" disabled={busy} onClick={() => load()}>
                                        <RefreshIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip size="sm" title="Lay work out over working days only">
                                    <Checkbox
                                        size="sm" label="Skip weekends" checked={skipWeekends}
                                        onChange={e => setSkipWeekends(e.target.checked)}
                                        sx={{ ml: 0.5 }}
                                    />
                                </Tooltip>
                            </>
                        )}
                        {renderer === 'google' && (
                            <Tooltip size="sm" title="Paint the chain of tasks that decides the end date">
                                <Checkbox
                                    size="sm" label="Critical path" checked={criticalPath}
                                    onChange={e => setCriticalPath(e.target.checked)}
                                />
                            </Tooltip>
                        )}
                        {renderer === 'react' && (
                            <>
                                <Tooltip size="sm" title="Zoom out">
                                    <IconButton size="sm" variant="outlined" disabled={!haveChart}
                                        onClick={() => setDayWidth(w => Math.max(2, w / 1.4))}>
                                        <ZoomOutIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip size="sm" title="Zoom in">
                                    <IconButton size="sm" variant="outlined" disabled={!haveChart}
                                        onClick={() => setDayWidth(w => Math.min(60, w * 1.4))}>
                                        <ZoomInIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip size="sm" title="Fit the whole schedule across the page">
                                    <IconButton size="sm" variant="outlined" disabled={!haveChart} onClick={fitZoom}>
                                        <FitScreenIcon />
                                    </IconButton>
                                </Tooltip>
                            </>
                        )}
                        {haveChart && (
                            <>
                                {/* No tooltip on this one: it opened directly
                                    below the control, which is where the menu's
                                    own first option lands - so reaching the top
                                    of the list meant reaching through a tooltip.
                                    What each mode does is said in the list
                                    itself, where it is being chosen. */}
                                <Select
                                    size="sm"
                                    value={colorBy}
                                    disabled={renderer === 'mermaid'}
                                    onChange={(_e, v) => v && setColorBy(v as string)}
                                    startDecorator={<PaletteIcon />}
                                    sx={{ minWidth: 148 }}
                                    // The button shows the name alone: an option
                                    // carries its explanation too, and without
                                    // this the control reads
                                    // "AssigneeASSIGNED / RID / RESOURCEID...".
                                    renderValue={opt => (
                                        <Typography level="body-sm">
                                            {COLOR_MODES.find(m => m.value === opt?.value)?.label || ''}
                                        </Typography>
                                    )}
                                >
                                    {COLOR_MODES.map(m => (
                                        <Option key={m.value} value={m.value}>
                                            <Box>
                                                <Typography level="body-sm">{m.label}</Typography>
                                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                                    {m.hint}
                                                </Typography>
                                            </Box>
                                        </Option>
                                    ))}
                                </Select>
                                {colorBy === 'property' && renderer !== 'mermaid' && (
                                    <Input
                                        size="sm"
                                        value={colorProp}
                                        onChange={e => setColorProp(e.target.value.toUpperCase())}
                                        placeholder="PROPERTY"
                                        sx={{ width: 130 }}
                                    />
                                )}
                            </>
                        )}
                        <ToggleButtonGroup
                            size="sm"
                            value={renderer}
                            onChange={(_e, v) => { if (v) { setSelected(''); setRenderer(v as GanttRenderer); } }}
                        >
                            <Button value="mermaid" startDecorator={<AccountTreeIcon />}>Mermaid</Button>
                            <Button value="react" startDecorator={<BarChartIcon />}>React</Button>
                            <Button value="vis" startDecorator={<TimelineIcon />}>Vis</Button>
                            <Button value="google" startDecorator={<TableChartIcon />}>Google</Button>
                        </ToggleButtonGroup>
                    </Box>
                </Box>
                {renderer === 'mermaid' && haveChart && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                        Mermaid colours by state only - it has four fixed task classes and no way to be
                        told about a fifth. Switch renderer for the other colour schemes.
                    </Typography>
                )}
                {renderer === 'react' && picked.length > 1 && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                        {`${picked.length} rows picked up - drag any of their grips to move them together, or `}
                        <Typography
                            component="span"
                            level="body-xs"
                            sx={{ color: 'primary.500', cursor: 'pointer' }}
                            onClick={() => setPicked([])}
                        >
                            let them go
                        </Typography>
                        .
                    </Typography>
                )}
                {interactive && haveChart && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                        {renderer === 'google'
                            ? 'Google’s gantt cannot be dragged - click a bar and edit it in the panel.'
                            : renderer === 'vis'
                                ? 'Drag a bar to move it, its edges to re-estimate, and into another lane to move lanes. The circles at either end draw a dependency onto another bar.'
                                : 'Drag a bar to move it, its right edge to re-estimate, the circle at its end onto the bar that should follow it. Drag the grip at the start of a row to reorder - shift or ctrl/⌘ picks up several at once. Click a lane heading to shut it.'}
                    </Typography>
                )}
            </Sheet>

            {error && (
                <Sheet variant="soft" color="danger" sx={{ borderRadius: 'sm', p: 2 }}>
                    <Typography level="body-sm">{error}</Typography>
                </Sheet>
            )}
            {!error && notice && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {busy ? 'Saving…' : notice}
                </Typography>
            )}

            {loading && (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                    <CircularProgress />
                </Box>
            )}

            {haveChart && !loading && scheme.legend.length > 0 && (
                <Sheet variant="soft" sx={{ borderRadius: 'sm', px: 1.5, py: 1 }}>
                    <Box sx={{ display: 'flex', gap: 1.75, alignItems: 'center', flexWrap: 'wrap' }}>
                        <Typography level="body-xs" sx={{ textTransform: 'uppercase', letterSpacing: '0.12em', color: 'text.tertiary' }}>
                            {scheme.title}
                        </Typography>
                        {scheme.legend.map(entry => (
                            <Box key={entry.label} sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                                <Box
                                    sx={{
                                        width: 13, height: 13, borderRadius: '3px', flexShrink: 0,
                                        // An entry with no colour of its own is the one that
                                        // says "these keep their own", so it is drawn as a
                                        // sample of nothing rather than as a colour.
                                        background: entry.color
                                            ? `linear-gradient(180deg, ${shade(entry.color, 0.17)}, ${entry.color} 52%, ${shade(entry.color, -0.09)})`
                                            : 'repeating-linear-gradient(45deg, #bbb 0 3px, #eee 3px 6px)',
                                        border: '1px solid',
                                        borderColor: entry.color ? shade(entry.color, -0.22) : 'neutral.400',
                                    }}
                                />
                                <Typography level="body-xs">
                                    {entry.label}
                                    {entry.count !== undefined && (
                                        <Typography component="span" level="body-xs" sx={{ color: 'text.tertiary' }}>
                                            {` ${entry.count}`}
                                        </Typography>
                                    )}
                                </Typography>
                            </Box>
                        ))}
                    </Box>
                </Sheet>
            )}

            <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start' }}>
                <Sheet
                    variant="outlined"
                    sx={{
                        borderRadius: 'sm',
                        p: 2,
                        overflow: 'auto',
                        flex: 1,
                        minWidth: 0,
                        bgcolor: colors.background,
                        display: haveChart && !loading ? 'block' : 'none',
                    }}
                >
                    {/* Every renderer gets its own container. They cannot share
                        one: mermaid writes its svg in through innerHTML, which
                        react would keep wiping out again. */}
                    <div ref={chartRef} style={{ display: renderer === 'mermaid' ? 'block' : 'none' }} />
                    <div ref={reactRef} style={{ display: renderer === 'react' ? 'block' : 'none' }}>
                        {renderer === 'react' && model && (
                            <ReactGantt
                                model={model}
                                colors={colors}
                                scheme={scheme}
                                collapsed={shutLanes}
                                onToggleLane={toggleLane}
                                title={chartTitle}
                                dayWidth={dayWidth}
                                selected={selected}
                                readOnly={busy}
                                onSelect={t => setSelected(t.hash || '')}
                                onMove={onMove}
                                onResize={onResize}
                                onLink={onLink}
                                picked={picked}
                                onPick={setPicked}
                                onReorderRows={onReorderRows}
                            />
                        )}
                    </div>
                    <div ref={visRef} style={{ display: renderer === 'vis' ? 'block' : 'none' }}>
                        {renderer === 'vis' && model && (
                            <VisGantt
                                model={model}
                                colors={colors}
                                scheme={scheme}
                                selected={selected}
                                readOnly={busy}
                                onSelect={t => setSelected(t.hash || '')}
                                onMove={onMove}
                                onResize={onResize}
                                onSection={onSection}
                                onLink={onLink}
                                onDelete={onDelete}
                                onAdd={(start) => {
                                    setNewTask(n => ({ ...n, start: dayKey(start) }));
                                    setAdding(true);
                                }}
                            />
                        )}
                    </div>
                    <div ref={googleRef} style={{ display: renderer === 'google' ? 'block' : 'none' }}>
                        {renderer === 'google' && model && (
                            <GoogleGantt
                                model={model}
                                colors={colors}
                                scheme={scheme}
                                selected={selected}
                                criticalPath={criticalPath}
                                onSelect={t => setSelected(t.hash || '')}
                            />
                        )}
                    </div>
                </Sheet>

                {interactive && selectedTask && !loading && (
                    // Stuck to the top of the window as the page scrolls: a
                    // chart is often taller than the screen, and a panel that
                    // stays behind at the top means scrolling back up to change
                    // the task you scrolled down to find. It scrolls inside
                    // itself if it is ever taller than the window.
                    <Box
                        sx={{
                            position: 'sticky',
                            top: 12,
                            alignSelf: 'flex-start',
                            maxHeight: 'calc(100dvh - 24px)',
                            overflowY: 'auto',
                            flexShrink: 0,
                        }}
                    >
                        <GanttInspector
                            task={selectedTask}
                            tasks={tasks}
                            statuses={statuses}
                            busy={busy}
                            onRun={runOps}
                            onClose={() => setSelected('')}
                        />
                    </Box>
                )}
            </Box>

            {model && model.errors.length > 0 && (
                <Sheet variant="soft" color="warning" sx={{ borderRadius: 'sm', p: 1.5 }}>
                    {model.errors.map((e, i) => (
                        <Typography key={i} level="body-xs">{e}</Typography>
                    ))}
                </Sheet>
            )}

            {/* Colours and title */}
            <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 2 }}>
                <Box sx={{ display: 'flex', gap: 2.5, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                    {COLOR_KEYS.map(key => (
                        <ColorInput
                            key={key}
                            label={colorLabels[key]}
                            value={colors[key]}
                            onChange={v => setColor(key, v)}
                        />
                    ))}
                    <FormControl size="sm" sx={{ minWidth: 180 }}>
                        <FormLabel sx={{ fontSize: '11px', mb: 0.25 }}>Title</FormLabel>
                        <input
                            type="text"
                            value={chartTitle}
                            onChange={e => setChartTitle(e.target.value)}
                            style={{
                                height: 28,
                                padding: '0 8px',
                                border: '1px solid #ccc',
                                borderRadius: 4,
                                fontSize: 13,
                                fontFamily: 'inherit',
                            }}
                        />
                    </FormControl>
                    <Button
                        size="sm" variant="plain"
                        onClick={() => { touched.current.clear(); setColors(paletteFor(appMode)); }}
                    >
                        Reset
                    </Button>
                    <Button
                        size="sm"
                        variant="solid"
                        startDecorator={<SaveIcon />}
                        disabled={!haveChart}
                        onClick={() => {
                            const svg = activeBox()?.innerHTML || '';
                            const title = chartTitle || 'Gantt Chart';
                            const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${title.replace(/"/g, '&quot;')}</title>
<style>
  body {
    margin: 0; padding: 24px;
    background: ${colors.background};
    color: ${legibleOn(colors.text, colors.background)};
    font-family: ${FONT_UI};
  }
  .chart { max-width: 100%; overflow-x: auto; }
</style>
</head>
<body>
<div class="chart">${svg}</div>
</body>
</html>`;
                            const blob = new Blob([html], { type: 'text/html' });
                            const url = URL.createObjectURL(blob);
                            const a = document.createElement('a');
                            a.href = url;
                            a.download = `${title.replace(/[^a-zA-Z0-9_-]/g, '_')}.html`;
                            a.click();
                            URL.revokeObjectURL(url);
                        }}
                    >
                        Save as HTML
                    </Button>
                </Box>
            </Sheet>

            {!haveChart && !loading && !error && (
                <Box sx={{ textAlign: 'center', p: 4 }}>
                    <Typography level="body-md" sx={{ color: 'text.secondary' }}>
                        Select a saved query and click Generate to view a Gantt chart.
                    </Typography>
                </Box>
            )}

            <Modal open={adding} onClose={() => setAdding(false)}>
                <ModalDialog sx={{ minWidth: 340 }}>
                    <Typography level="title-md">Add a task</Typography>
                    <Divider sx={{ my: 1 }} />
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
                        <FormControl size="sm">
                            <FormLabel>Name</FormLabel>
                            <Input
                                size="sm" autoFocus value={newTask.headline}
                                onChange={e => setNewTask({ ...newTask, headline: e.target.value })}
                                onKeyDown={e => { if (e.key === 'Enter') doAdd(); }}
                            />
                        </FormControl>
                        <FormControl size="sm">
                            <FormLabel>Beside</FormLabel>
                            <Select
                                size="sm"
                                value={newTask.parent}
                                onChange={(_e, v) => setNewTask({ ...newTask, parent: (v as string) || '' })}
                            >
                                <Option value="">(the end of the first file in this chart)</Option>
                                {tasks.filter(t => t.hash && !t.implied).map(t => (
                                    <Option key={t.hash} value={t.hash as string}>{t.name}</Option>
                                ))}
                            </Select>
                        </FormControl>
                        <Box sx={{ display: 'flex', gap: 1 }}>
                            <FormControl size="sm" sx={{ flex: 1 }}>
                                <FormLabel>Keyword</FormLabel>
                                <Input size="sm" value={newTask.status}
                                    onChange={e => setNewTask({ ...newTask, status: e.target.value })} />
                            </FormControl>
                            <FormControl size="sm" sx={{ flex: 1 }}>
                                <FormLabel>Starts</FormLabel>
                                <Input size="sm" type="date" value={newTask.start}
                                    onChange={e => setNewTask({ ...newTask, start: e.target.value })} />
                            </FormControl>
                            <FormControl size="sm" sx={{ width: 90 }}>
                                <FormLabel>Days</FormLabel>
                                <Input size="sm" type="number" value={newTask.effort}
                                    slotProps={{ input: { min: 0.5, step: 0.5 } }}
                                    onChange={e => setNewTask({ ...newTask, effort: e.target.value })} />
                            </FormControl>
                        </Box>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            The task is written as the last child of whatever it is put beside,
                            so it lands in the same file and lane as its neighbours.
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                            <Button size="sm" variant="plain" onClick={() => setAdding(false)}>Cancel</Button>
                            <Button size="sm" disabled={!newTask.headline.trim()} onClick={doAdd}>Add</Button>
                        </Box>
                    </Box>
                </ModalDialog>
            </Modal>
        </Box>
    );
}
