// The link graph, drawn as plain svg. The layout is a small force simulation -
// nodes push each other apart, links pull their two ends together, and everything
// drifts towards the middle - run on an animation frame until it settles. That is
// a few dozen lines here and saves carrying a graph library for a picture of at
// most a few hundred nodes.
//
// The thing the drawing is really trying to say is which links run both ways. A
// one way link is a thin neutral stroke with a single arrow head; a pair of nodes
// that link at each other is one thicker violet stroke with a head at each end,
// so a bidirectional link reads as a single relationship rather than two
// overlapping arrows.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import { LinkGraphResult, LinkGraphNode } from '../db';

type Pt = { x: number; y: number; vx: number; vy: number; fixed: boolean };

export type LinkGraphProps = {
    data: LinkGraphResult | null;
    height?: number;
    onPick?: (node: LinkGraphNode) => void;
    selected?: string;
};

// Joy tokens, so the picture follows the colour scheme rather than fighting it.
const C = {
    oneWay: 'var(--joy-palette-neutral-400)',
    both: 'var(--joy-palette-primary-400)',
    broken: 'var(--joy-palette-danger-400)',
    file: 'var(--joy-palette-primary-500)',
    heading: 'var(--joy-palette-success-500)',
    center: 'var(--joy-palette-warning-400)',
    ring: 'var(--joy-palette-background-surface)',
    text: 'var(--joy-palette-text-primary)',
    dim: 'var(--joy-palette-text-tertiary)',
};

function radius(n: LinkGraphNode): number {
    const deg = n.In + n.Out;
    return (n.Center ? 11 : 7) + Math.sqrt(deg) * 2.2;
}

function shortLabel(s: string, max: number = 18): string {
    if (s.length <= max) return s;
    return s.slice(0, max - 1) + '…';
}

// Lay the nodes out before the simulation starts: the center in the middle, the
// rest on a ring per hop, spread by the golden angle. Seeding it this way rather
// than at random means the same graph settles the same way every time.
function seed(nodes: LinkGraphNode[], w: number, h: number): Map<string, Pt> {
    const pos = new Map<string, Pt>();
    const cx = w / 2;
    const cy = h / 2;
    const maxDist = nodes.reduce((m, n) => Math.max(m, n.Distance), 0);
    const step = Math.min(w, h) / (2 * (maxDist + 1.4));
    let i = 0;
    for (const n of nodes) {
        if (n.Center) {
            pos.set(n.Id, { x: cx, y: cy, vx: 0, vy: 0, fixed: false });
            continue;
        }
        const a = (i + 1) * 2.399963229728653; // golden angle
        const r = step * (n.Distance === 0 ? 0.9 : n.Distance) + (i % 3) * 6;
        pos.set(n.Id, { x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r, vx: 0, vy: 0, fixed: false });
        i++;
    }
    return pos;
}

export default function LinkGraph({ data, height = 320, onPick, selected }: LinkGraphProps) {
    const wrapRef = React.useRef<HTMLDivElement>(null);
    const [size, setSize] = React.useState({ w: 520, h: height });
    const [hover, setHover] = React.useState<string | null>(null);
    // Positions live in a ref and are copied into state once per frame, so the
    // simulation is not fighting React over who owns the numbers.
    const posRef = React.useRef<Map<string, Pt>>(new Map());
    // Bumped to repaint after a simulation step; the positions themselves live
    // in the ref, so the value is never read.
    const [, setTick] = React.useState(0);
    const dragRef = React.useRef<{ id: string; dx: number; dy: number } | null>(null);
    const frameRef = React.useRef<number | null>(null);
    const alphaRef = React.useRef(1);
    const stepRef = React.useRef<() => void>(() => {});

    const nodes = React.useMemo(() => (data && data.Nodes) || [], [data]);
    const edges = React.useMemo(() => (data && data.Edges) || [], [data]);

    React.useEffect(() => {
        const el = wrapRef.current;
        if (!el) return;
        const ro = new ResizeObserver(entries => {
            for (const e of entries) {
                const w = Math.max(240, Math.round(e.contentRect.width));
                setSize(s => (s.w === w ? s : { w, h: height }));
            }
        });
        ro.observe(el);
        setSize({ w: Math.max(240, Math.round(el.clientWidth)), h: height });
        return () => ro.disconnect();
    }, [height]);

    // Which nodes sit at each end of an edge, and who is adjacent to whom.
    const adj = React.useMemo(() => {
        const m = new Map<string, Set<string>>();
        for (const e of edges) {
            if (!m.has(e.From)) m.set(e.From, new Set());
            if (!m.has(e.To)) m.set(e.To, new Set());
            m.get(e.From)!.add(e.To);
            m.get(e.To)!.add(e.From);
        }
        return m;
    }, [edges]);

    // Restart the simulation whenever the graph or the box it lives in changes.
    React.useEffect(() => {
        if (nodes.length === 0) {
            posRef.current = new Map();
            setTick(t => t + 1);
            return;
        }
        const old = posRef.current;
        const next = seed(nodes, size.w, size.h);
        // Keep a node where it already was, so a depth change does not throw the
        // whole picture in the air.
        next.forEach((p, id) => {
            const prev = old.get(id);
            if (prev) {
                p.x = prev.x;
                p.y = prev.y;
            }
        });
        posRef.current = next;
        alphaRef.current = 1;

        const ids = nodes.map(n => n.Id);
        const rad = new Map(nodes.map(n => [n.Id, radius(n)] as [string, number]));
        // Half the width the label under a node takes up, near enough for the
        // separation below. The center node is set slightly bigger and bolder.
        const labelHalf = new Map(nodes.map(n =>
            [n.Id, shortLabel(n.Label).length * (n.Center ? 3.4 : 2.9)] as [string, number]));
        const centerId = nodes.find(n => n.Center)?.Id;
        // The spring length the layout aims for: repulsion k*k/d and attraction
        // d*d/k balance at exactly d = k, so this is the distance a pair of
        // linked nodes settles at. Room for the whole picture, but never so wide
        // that two nodes cannot both be on screen.
        const k = Math.min(
            Math.min(size.w, size.h) / 2.2,
            Math.max(46, Math.sqrt((size.w * size.h) / Math.max(1, nodes.length)) * 0.62)
        );
        const FORCE = 0.05;

        const step = () => {
            const pos = posRef.current;
            const a = alphaRef.current;
            // Push every pair apart.
            for (let i = 0; i < ids.length; i++) {
                const pi = pos.get(ids[i])!;
                for (let j = i + 1; j < ids.length; j++) {
                    const pj = pos.get(ids[j])!;
                    let dx = pi.x - pj.x;
                    let dy = pi.y - pj.y;
                    let d2 = dx * dx + dy * dy;
                    if (d2 < 0.01) {
                        dx = (i - j) * 0.5 + 0.3;
                        dy = 0.4;
                        d2 = dx * dx + dy * dy;
                    }
                    const d = Math.sqrt(d2);
                    const want = rad.get(ids[i])! + rad.get(ids[j])! + 26;
                    // Ordinary repulsion, plus a harder shove when two circles
                    // would otherwise overlap.
                    let f = ((k * k) / d) * FORCE;
                    if (d < want) f += (want - d) * 0.9;
                    const fx = (dx / d) * f;
                    const fy = (dy / d) * f;
                    pi.vx += fx;
                    pi.vy += fy;
                    pj.vx -= fx;
                    pj.vy -= fy;
                    // A label sits under its node, so two nodes at a similar
                    // height run their text together long before their circles
                    // touch. That is pushed apart sideways only, rather than by
                    // growing the whole layout to make room for it.
                    const labWant = labelHalf.get(ids[i])! + labelHalf.get(ids[j])! + 6;
                    if (Math.abs(dy) < 16 && Math.abs(dx) < labWant) {
                        const push = (labWant - Math.abs(dx)) * 0.5;
                        const dir = dx >= 0 ? 1 : -1;
                        pi.vx += dir * push;
                        pj.vx -= dir * push;
                    }
                }
            }
            // Pull linked nodes together, harder when there are more links on the edge.
            for (const e of edges) {
                const pa = pos.get(e.From);
                const pb = pos.get(e.To);
                if (!pa || !pb) continue;
                const dx = pb.x - pa.x;
                const dy = pb.y - pa.y;
                const d = Math.max(1, Math.sqrt(dx * dx + dy * dy));
                const weight = 1 + Math.min(2, Math.log2(1 + e.Count + e.Back)) * 0.35;
                const f = ((d * d) / k) * FORCE * weight;
                const fx = (dx / d) * f;
                const fy = (dy / d) * f;
                pa.vx += fx;
                pa.vy += fy;
                pb.vx -= fx;
                pb.vy -= fy;
            }
            // Drift towards the middle and settle.
            const cx = size.w / 2;
            const cy = size.h / 2;
            for (const id of ids) {
                const p = pos.get(id)!;
                if (p.fixed) {
                    p.vx = 0;
                    p.vy = 0;
                    continue;
                }
                const pull = id === centerId ? 0.22 : 0.035;
                p.vx += (cx - p.x) * pull;
                p.vy += (cy - p.y) * pull;
                p.vx *= 0.82;
                p.vy *= 0.82;
                const maxStep = 28;
                p.x += Math.max(-maxStep, Math.min(maxStep, p.vx * a));
                p.y += Math.max(-maxStep, Math.min(maxStep, p.vy * a));
                const r = rad.get(id)! + 4;
                p.x = Math.max(r, Math.min(size.w - r, p.x));
                p.y = Math.max(r + 2, Math.min(size.h - r - 12, p.y));
            }
            alphaRef.current = a * 0.965;
            setTick(t => t + 1);
            if (alphaRef.current > 0.012 || dragRef.current !== null) {
                frameRef.current = requestAnimationFrame(step);
            } else {
                frameRef.current = null;
            }
        };
        stepRef.current = step;
        frameRef.current = requestAnimationFrame(step);
        return () => {
            if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
            frameRef.current = null;
        };
    }, [nodes, edges, size.w, size.h]);

    // Put some energy back in and make sure a frame is pending. Restarting the
    // loop here rather than from an effect matters: an effect that reschedules
    // itself off its own state update never stops, because nothing decays alpha
    // unless a simulation step actually runs.
    const kick = React.useCallback((a: number) => {
        alphaRef.current = Math.max(alphaRef.current, a);
        if (frameRef.current === null) {
            frameRef.current = requestAnimationFrame(() => stepRef.current());
        }
    }, []);

    // Dragging a node wakes the simulation and pins that node under the pointer.
    const onPointerDown = (e: React.PointerEvent, id: string) => {
        const p = posRef.current.get(id);
        const svg = (e.currentTarget as SVGElement).ownerSVGElement;
        if (!p || !svg) return;
        const box = svg.getBoundingClientRect();
        dragRef.current = { id, dx: p.x - (e.clientX - box.left), dy: p.y - (e.clientY - box.top) };
        p.fixed = true;
        (e.target as Element).setPointerCapture?.(e.pointerId);
        kick(0.35);
    };

    const onPointerMove = (e: React.PointerEvent) => {
        const drag = dragRef.current;
        if (!drag) return;
        const svg = (e.currentTarget as SVGSVGElement);
        const box = svg.getBoundingClientRect();
        const p = posRef.current.get(drag.id);
        if (!p) return;
        p.x = e.clientX - box.left + drag.dx;
        p.y = e.clientY - box.top + drag.dy;
        setTick(t => t + 1);
    };

    const endDrag = () => {
        const drag = dragRef.current;
        if (!drag) return;
        const p = posRef.current.get(drag.id);
        if (p) p.fixed = false;
        dragRef.current = null;
        kick(0.25);
    };

    if (!data) {
        return (
            <Box ref={wrapRef} sx={{ height, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>No graph yet.</Typography>
            </Box>
        );
    }
    if (nodes.length === 0) {
        return (
            <Box ref={wrapRef} sx={{ height, display: 'flex', alignItems: 'center', justifyContent: 'center', px: 2, textAlign: 'center' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {data.Msg !== '' ? data.Msg : 'Nothing links to or from this file yet.'}
                </Typography>
            </Box>
        );
    }

    const pos = posRef.current;
    // Only one node at a time is lit, and only while it is pointed at or a
    // caller has picked one out: with nothing lit the whole graph draws at full
    // strength rather than dimming itself down to one neighbourhood.
    const lit = hover !== null ? hover : (selected || null);
    const near = lit !== null ? adj.get(lit) : undefined;
    const isLit = (id: string) => lit === null || lit === id || (near !== undefined && near.has(id));

    return (
        <Box ref={wrapRef} sx={{ width: '100%', height, position: 'relative' }}>
            <svg
                width={size.w}
                height={size.h}
                viewBox={`0 0 ${size.w} ${size.h}`}
                style={{ display: 'block', touchAction: 'none', cursor: dragRef.current ? 'grabbing' : 'default' }}
                onPointerMove={onPointerMove}
                onPointerUp={endDrag}
                onPointerLeave={endDrag}
            >
                <defs>
                    <radialGradient id="lg-glow">
                        <stop offset="0%" stopColor={C.center} stopOpacity="0.42" />
                        <stop offset="100%" stopColor={C.center} stopOpacity="0" />
                    </radialGradient>
                    <radialGradient id="lg-wash" cx="50%" cy="45%">
                        <stop offset="0%" stopColor={C.both} stopOpacity="0.10" />
                        <stop offset="100%" stopColor={C.both} stopOpacity="0" />
                    </radialGradient>
                    {[
                        { id: 'lg-head-one', fill: C.oneWay },
                        { id: 'lg-head-both', fill: C.both },
                        { id: 'lg-head-broken', fill: C.broken },
                    ].map(m => (
                        <marker
                            key={m.id}
                            id={m.id}
                            viewBox="0 0 10 10"
                            refX="9"
                            refY="5"
                            markerWidth="6"
                            markerHeight="6"
                            orient="auto-start-reverse"
                        >
                            <path d="M 0 1 L 10 5 L 0 9 z" fill={m.fill} />
                        </marker>
                    ))}
                </defs>

                <rect x="0" y="0" width={size.w} height={size.h} fill="url(#lg-wash)" />

                {/* Edges first, so the nodes sit on top of them. */}
                <g>
                    {edges.map(e => {
                        const pa = pos.get(e.From);
                        const pb = pos.get(e.To);
                        if (!pa || !pb) return null;
                        const on = isLit(e.From) && isLit(e.To);
                        const stroke = e.Broken ? C.broken : e.Both ? C.both : C.oneWay;
                        const head = e.Broken ? 'lg-head-broken' : e.Both ? 'lg-head-both' : 'lg-head-one';
                        const width = (e.Both ? 2.1 : 1.2) + Math.min(2.6, Math.log2(1 + e.Count + e.Back) * 0.7);
                        // A gentle bow, so two nodes are joined by a curve rather
                        // than a ruled line and crossings stay readable.
                        const mx = (pa.x + pb.x) / 2;
                        const my = (pa.y + pb.y) / 2;
                        const dx = pb.x - pa.x;
                        const dy = pb.y - pa.y;
                        const len = Math.max(1, Math.hypot(dx, dy));
                        const bow = Math.min(26, len * 0.14);
                        const qx = mx - (dy / len) * bow;
                        const qy = my + (dx / len) * bow;
                        const label = e.Both
                            ? `${e.Count + e.Back} links, both ways`
                            : `${e.Count + e.Back} link${e.Count + e.Back === 1 ? '' : 's'}`;
                        return (
                            <path
                                key={`${e.From}|${e.To}`}
                                d={`M ${pa.x.toFixed(1)} ${pa.y.toFixed(1)} Q ${qx.toFixed(1)} ${qy.toFixed(1)} ${pb.x.toFixed(1)} ${pb.y.toFixed(1)}`}
                                fill="none"
                                stroke={stroke}
                                strokeWidth={width}
                                strokeLinecap="round"
                                strokeDasharray={e.Broken ? '5 4' : undefined}
                                opacity={on ? (e.Both ? 0.95 : 0.7) : 0.12}
                                markerEnd={e.Count > 0 ? `url(#${head})` : undefined}
                                markerStart={e.Back > 0 ? `url(#${head})` : undefined}
                            >
                                <title>{label}</title>
                            </path>
                        );
                    })}
                </g>

                {/* Nodes */}
                <g>
                    {nodes.map(n => {
                        const p = pos.get(n.Id);
                        if (!p) return null;
                        const r = radius(n);
                        const on = isLit(n.Id);
                        const fill = n.Center ? C.center : n.Kind === 'heading' ? C.heading : C.file;
                        return (
                            <g
                                key={n.Id}
                                transform={`translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})`}
                                opacity={on ? 1 : 0.22}
                                style={{ cursor: 'pointer' }}
                                onPointerDown={e => onPointerDown(e, n.Id)}
                                onMouseEnter={() => setHover(n.Id)}
                                onMouseLeave={() => setHover(null)}
                                onClick={() => {
                                    if (dragRef.current === null && onPick) onPick(n);
                                }}
                            >
                                {n.Center && <circle r={r * 2.6} fill="url(#lg-glow)" />}
                                <circle r={r} fill={fill} stroke={C.ring} strokeWidth={2} />
                                {n.Kind === 'heading' && <circle r={Math.max(2, r * 0.32)} fill={C.ring} opacity={0.75} />}
                                <text
                                    y={r + 12}
                                    textAnchor="middle"
                                    fontSize={n.Center ? 12 : 10.5}
                                    fontWeight={n.Center ? 700 : 500}
                                    fill={C.text}
                                    stroke={C.ring}
                                    strokeWidth={3}
                                    paintOrder="stroke"
                                    style={{ pointerEvents: 'none', userSelect: 'none' }}
                                >
                                    {shortLabel(n.Label)}
                                </text>
                                <title>
                                    {`${n.Label}\n${n.Filename}\n${n.In} in, ${n.Out} out`}
                                </title>
                            </g>
                        );
                    })}
                </g>
            </svg>

            {/* Legend */}
            <Box
                sx={{
                    position: 'absolute',
                    left: 6,
                    bottom: 4,
                    display: 'flex',
                    gap: 1.25,
                    alignItems: 'center',
                    pointerEvents: 'none',
                    flexWrap: 'wrap',
                }}
            >
                {[
                    { c: C.both, t: 'both ways' },
                    { c: C.oneWay, t: 'one way' },
                    { c: C.broken, t: 'broken' },
                ].map(l => (
                    <Box key={l.t} sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                        <Box sx={{ width: 14, height: 0, borderTop: '2px solid', borderColor: l.c }} />
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', fontSize: 10 }}>{l.t}</Typography>
                    </Box>
                ))}
            </Box>
        </Box>
    );
}
