// ---------------------------------------------------------------------------
// Small pieces
// ---------------------------------------------------------------------------

function baseName(path: string): string {
    const parts = path.split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

function isSetDate(d?: { Start?: string } | null): boolean {
    return !!(d && d.Start && !d.Start.startsWith('0001-01-01'));
}

// A date said the way a person reads it on a card: today and tomorrow by name,
// this year without the year, anything else in full.
function dateLabel(iso: string): string {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    const now = new Date();
    const days = Math.round((new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
        - new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()) / 86400000);
    if (days === 0) return 'today';
    if (days === 1) return 'tomorrow';
    if (days === -1) return 'yesterday';
    if (days > 1 && days < 7) return d.toLocaleDateString(undefined, { weekday: 'short' });
    const opts: Intl.DateTimeFormatOptions = d.getFullYear() === now.getFullYear()
        ? { month: 'short', day: 'numeric' }
        : { year: 'numeric', month: 'short', day: 'numeric' };
    return d.toLocaleDateString(undefined, opts);
}

function isOverdue(iso: string): boolean {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return false;
    const now = new Date();
    return d.getTime() < new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
}

const PRIORITY_COLOR: Record<string, string> = { A: '#e5484d', B: '#f5a524', C: '#3e63dd' };

// ---------------------------------------------------------------------------
// A card
// ---------------------------------------------------------------------------

type CardProps = {
    card: Card;
    board: KanbanBoard;
    flipped: boolean;
    dim: boolean;
    dragging: boolean;
    onFlip: () => void;
    onDragStart: (e: React.DragEvent) => void;
    onDragEnd: () => void;
    onDragOverCard: (e: React.DragEvent) => void;
    onAct: (what: 'archive' | 'clockin' | 'clockout', card: Card) => void;
    clocked: boolean;
};

function CardFront({ card, board, sw }: { card: Card; board: KanbanBoard; sw: { hex: string } | null }) {
    const tags = card.Tags || [];
    const badges = (board.badges || [])
        .map(name => ({ name, value: card.Props ? card.Props[name] : undefined }))
        .filter(b => b.value !== undefined && b.value !== '');
    const deadline = isSetDate(card.Deadline) ? card.Deadline!.Start! : '';
    const scheduled = isSetDate(card.Date) ? card.Date!.Start! : '';
    // The keyword is worth a chip except on a board that is already split by
    // it, where every card in a column would wear the same one.
    const showStatus = card.Status !== '' && board.groupBy !== 'status';

    return (
        <Box sx={{ p: 1.25, pl: 1.5, display: 'flex', flexDirection: 'column', gap: 0.75, height: '100%', minWidth: 0 }}>
            <Box sx={{ display: 'flex', gap: 0.75, alignItems: 'flex-start', minWidth: 0 }}>
                {card.Priority && (
                    <Box
                        sx={{
                            flexShrink: 0, mt: '2px', px: 0.5, borderRadius: 3, fontSize: 10, fontWeight: 'lg',
                            lineHeight: '16px', color: '#fff',
                            background: PRIORITY_COLOR[card.Priority.toUpperCase()] || '#6b7280',
                        }}
                    >
                        {card.Priority.toUpperCase()}
                    </Box>
                )}
                <Typography
                    level="body-sm"
                    sx={{
                        fontWeight: 'md', lineHeight: 1.35, minWidth: 0,
                        display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden',
                    }}
                >
                    {card.Headline || '(no headline)'}
                </Typography>
            </Box>

            {(showStatus || tags.length > 0 || badges.length > 0) && (
                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', alignItems: 'center' }}>
                    {showStatus && (
                        <Chip size="sm" variant="soft" color="neutral" sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}>
                            {card.Status}
                        </Chip>
                    )}
                    {badges.map(b => (
                        <Chip
                            key={b.name}
                            size="sm"
                            variant="outlined"
                            sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}
                            title={`${b.name}: ${b.value}`}
                        >
                            {b.value}
                        </Chip>
                    ))}
                    {tags.map(t => (
                        <Box
                            key={t}
                            sx={{
                                fontSize: 10, px: 0.6, borderRadius: 3, lineHeight: '16px',
                                background: tint(autoSwatch(t).hex, 0.18),
                                color: 'text.secondary',
                            }}
                        >
                            {t}
                        </Box>
                    ))}
                </Box>
            )}

            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', mt: 'auto', minWidth: 0 }}>
                {deadline && (
                    <Tooltip size="sm" title={`Deadline ${deadline.substring(0, 10)}`}>
                        <Box sx={{
                            display: 'flex', alignItems: 'center', gap: 0.25, fontSize: 10,
                            color: isOverdue(deadline) ? 'danger.500' : 'text.tertiary',
                            fontWeight: isOverdue(deadline) ? 'lg' : 'md',
                        }}>
                            <FlagIcon sx={{ fontSize: 12 }} />{dateLabel(deadline)}
                        </Box>
                    </Tooltip>
                )}
                {scheduled && (
                    <Tooltip size="sm" title={`Scheduled ${scheduled.substring(0, 10)}`}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25, fontSize: 10, color: 'text.tertiary' }}>
                            <ScheduleIcon sx={{ fontSize: 12 }} />{dateLabel(scheduled)}
                        </Box>
                    </Tooltip>
                )}
                <Typography level="body-xs" sx={{ ml: 'auto', color: 'text.tertiary', fontSize: 10 }} noWrap title={card.Filename}>
                    {baseName(card.Filename)}
                </Typography>
            </Box>

            {sw && <Box sx={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 4, background: sw.hex, borderRadius: '6px 0 0 6px' }} />}
        </Box>
    );
}

function CardBack({ card, board, clocked, onAct }: {
    card: Card; board: KanbanBoard; clocked: boolean;
    onAct: (what: 'archive' | 'clockin' | 'clockout', card: Card) => void;
}) {
    const [html, setHtml] = React.useState<string | null>(null);
    const [loading, setLoading] = React.useState(false);
    const wants = board.backShows === 'body' || board.backShows === 'both';

    // One fetch, when the back is first mounted - which the card only does once
    // it has been turned over, so a column of forty cards is not forty requests
    // for text nobody asked to read. Note what is *not* in the dependency list:
    // loading and html both change while this is running, and either of them in
    // there would tear the effect down and cancel the fetch it just started.
    React.useEffect(() => {
        if (!wants) return;
        let alive = true;
        setLoading(true);
        ODb.todoHtml(card.Hash).then(r => {
            if (!alive) return;
            setHtml((r && r.Content) || '');
            setLoading(false);
        }).catch(() => { if (alive) { setHtml(''); setLoading(false); } });
        return () => { alive = false; };
    }, [card.Hash, wants]);

    const props = card.Props || {};
    const propNames = Object.keys(props).filter(k => props[k] !== '');
    const showProps = board.backShows === 'properties' || board.backShows === 'both';

    return (
        <Box sx={{ p: 1.25, display: 'flex', flexDirection: 'column', height: '100%', minWidth: 0 }}>
            <Typography level="body-xs" sx={{ fontWeight: 'lg', mb: 0.5 }} noWrap title={card.Headline}>
                {card.Headline}
            </Typography>
            <Box sx={{ flex: 1, overflowY: 'auto', minHeight: 0, pr: 0.5 }}>
                {wants && (
                    loading ? <LinearProgress size="sm" sx={{ my: 1 }} /> : (
                        html === '' || html === null ? (
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                                Nothing written under this heading.
                            </Typography>
                        ) : (
                            <Box
                                sx={{
                                    fontSize: 11.5, lineHeight: 1.45, color: 'text.secondary',
                                    '& p': { m: 0, mb: 0.5 },
                                    '& ul, & ol': { m: 0, pl: 2 },
                                    '& img': { maxWidth: '100%' },
                                    '& pre': { fontSize: 10, overflowX: 'auto', p: 0.5, borderRadius: 4, background: 'var(--joy-palette-background-level2)' },
                                    '& table': { fontSize: 10, borderCollapse: 'collapse' },
                                    '& td, & th': { border: '1px solid var(--joy-palette-divider)', px: 0.5 },
                                    '& h1, & h2, & h3, & h4': { fontSize: 12, m: 0, mt: 0.5, mb: 0.25 },
                                }}
                                dangerouslySetInnerHTML={{ __html: html }}
                            />
                        )
                    )
                )}
                {showProps && propNames.length > 0 && (
                    <Box sx={{ mt: wants ? 1 : 0 }}>
                        {propNames.map(k => (
                            <Box key={k} sx={{ display: 'flex', gap: 1, fontSize: 10.5, lineHeight: 1.6, minWidth: 0 }}>
                                <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontSize: 10, color: 'text.tertiary', flexShrink: 0 }}>
                                    {k}
                                </Typography>
                                <Typography level="body-xs" sx={{ fontSize: 10.5, minWidth: 0 }} noWrap title={props[k]}>
                                    {props[k]}
                                </Typography>
                            </Box>
                        ))}
                    </Box>
                )}
                {showProps && propNames.length === 0 && !wants && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                        No properties on this heading.
                    </Typography>
                )}
            </Box>
            <Divider sx={{ my: 0.75 }} />
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }}>
                <Tooltip size="sm" title={`${card.Filename}:${card.LineNum}`}>
                    <Typography level="body-xs" sx={{ fontSize: 10, color: 'text.tertiary', minWidth: 0 }} noWrap>
                        <ArticleIcon sx={{ fontSize: 11, mr: 0.25, verticalAlign: '-1px' }} />
                        {baseName(card.Filename)}:{card.LineNum}
                    </Typography>
                </Tooltip>
                <Box sx={{ ml: 'auto', display: 'flex', gap: 0.25 }} onClick={e => e.stopPropagation()}>
                    <Tooltip size="sm" title={clocked ? 'Clock out' : 'Clock in on this heading'}>
                        <IconButton size="sm" variant="plain" color={clocked ? 'danger' : 'neutral'}
                            onClick={() => onAct(clocked ? 'clockout' : 'clockin', card)}>
                            {clocked ? <StopIcon sx={{ fontSize: 14 }} /> : <PlayArrowIcon sx={{ fontSize: 14 }} />}
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="Archive this heading">
                        <IconButton size="sm" variant="plain" color="neutral" onClick={() => onAct('archive', card)}>
                            <Inventory2Icon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>
        </Box>
    );
}

// A card is two faces turned by a click and a thing you can pick up and drop
// somewhere else.
//
// The height is the front's own - a third copy of the front is rendered in the
// flow, hidden, purely to give the box a height, because a face that turns has
// to be positioned absolutely and an absolute box has no height of its own. The
// back is given room to breathe when it is showing and gives it back when it is
// not, which is what the min-height transition is.
function KanbanCardView(props: CardProps) {
    const { card, board, flipped, dim, dragging, onFlip, onDragStart, onDragEnd, onDragOverCard, onAct, clocked } = props;
    const sw = cardSwatch(card, board);
    // A drag that ends over the same card still fires a click in some browsers,
    // so the flip asks whether a drag has just happened rather than trusting it.
    const dragged = React.useRef(false);
    // The back is built the first time the card is turned over and then kept,
    // so turning it back and forth does not fetch the text again. Before that
    // the face is there but empty - it is facing away from the reader, and what
    // it would have cost is a request per card on the board.
    const [revealed, setRevealed] = React.useState(flipped);
    if (flipped && !revealed) setRevealed(true);

    const faceSx = {
        position: 'absolute' as const,
        inset: 0,
        borderRadius: 'sm',
        overflow: 'hidden',
        backfaceVisibility: 'hidden' as const,
        WebkitBackfaceVisibility: 'hidden' as const,
        border: '1px solid',
        borderColor: sw ? tint(sw.hex, 0.45) : 'divider',
        background: sw
            ? `linear-gradient(180deg, ${tint(sw.hex, 0.14)}, ${tint(sw.hex, 0.05)}), var(--joy-palette-background-surface)`
            : 'var(--joy-palette-background-surface)',
        boxShadow: 'sm',
    };

    return (
        <Box
            draggable
            onDragStart={e => { dragged.current = true; onDragStart(e); }}
            onDragEnd={() => { onDragEnd(); window.setTimeout(() => { dragged.current = false; }, 0); }}
            onDragOver={onDragOverCard}
            onClick={() => { if (!dragged.current) onFlip(); }}
            sx={{
                position: 'relative',
                perspective: '1400px',
                cursor: 'grab',
                mb: 1,
                opacity: dragging ? 0.35 : dim ? 0.35 : 1,
                filter: dim ? 'saturate(0.3)' : 'none',
                transition: 'opacity 0.2s, filter 0.2s, min-height 0.3s ease',
                minHeight: flipped ? 210 : 0,
                '&:active': { cursor: 'grabbing' },
                '&:hover .kb-flip': { opacity: 1 },
            }}
        >
            {/* The sizer: the front again, in the flow and invisible, so the
                card is as tall as its own headline rather than a guess. */}
            <Box sx={{ visibility: 'hidden', pointerEvents: 'none' }} aria-hidden>
                <CardFront card={card} board={board} sw={sw} />
            </Box>

            <Box
                sx={{
                    position: 'absolute', inset: 0,
                    transformStyle: 'preserve-3d',
                    transition: 'transform 0.55s cubic-bezier(0.2, 0.7, 0.25, 1)',
                    transform: flipped ? 'rotateY(180deg)' : 'rotateY(0deg)',
                }}
            >
                <Sheet sx={faceSx}>
                    <CardFront card={card} board={board} sw={sw} />
                </Sheet>
                <Sheet sx={{ ...faceSx, transform: 'rotateY(180deg)' }}>
                    {revealed && <CardBack card={card} board={board} clocked={clocked} onAct={onAct} />}
                </Sheet>
            </Box>

            <Box
                className="kb-flip"
                sx={{
                    position: 'absolute', top: 2, right: 2, opacity: 0, transition: 'opacity 0.15s',
                    pointerEvents: 'none', color: 'text.tertiary',
                }}
            >
                <FlipIcon sx={{ fontSize: 13 }} />
            </Box>
        </Box>
    );
}

// ---------------------------------------------------------------------------
// A column
// ---------------------------------------------------------------------------

function Column({
    col, cards, board, flipped, terms, dropIndex, isDropTarget, draggingHash, clockedHash,
    onFlip, onCollapse, onDragStart, onDragEnd, onDragOverAt, onDrop, onAct, dropRefused,
}: {
    col: KanbanColumn;
    cards: Card[];
    board: KanbanBoard;
    flipped: Set<string>;
    terms: string[];
    dropIndex: number | null;
    isDropTarget: boolean;
    draggingHash: string | null;
    clockedHash: string;
    onFlip: (hash: string) => void;
    onCollapse: (value: string, collapsed: boolean) => void;
    onDragStart: (card: Card) => void;
    onDragEnd: () => void;
    onDragOverAt: (value: string, index: number) => void;
    onDrop: (value: string) => void;
    onAct: (what: 'archive' | 'clockin' | 'clockout', card: Card) => void;
    dropRefused: boolean;
}) {
    const sw = col.color ? swatch(col.color) : autoSwatch(col.value || 'unset');
    const over = col.limit > 0 && cards.length > col.limit;
    const title = columnTitle(col) || 'Untitled';

    if (col.collapsed) {
        return (
            <Sheet
                variant="outlined"
                sx={{
                    width: 44, flexShrink: 0, borderRadius: 'sm', display: 'flex', flexDirection: 'column',
                    alignItems: 'center', py: 1, gap: 1, cursor: 'pointer',
                    borderTop: '3px solid', borderTopColor: sw.hex,
                    background: tint(sw.hex, 0.06),
                }}
                onClick={() => onCollapse(col.value, false)}
            >
                <Tooltip size="sm" title={`Open ${title}`}>
                    <ChevronRightIcon fontSize="small" />
                </Tooltip>
                <Chip size="sm" variant="soft" sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}>{cards.length}</Chip>
                <Typography
                    level="body-xs"
                    sx={{ writingMode: 'vertical-rl', textOrientation: 'mixed', fontWeight: 'lg', color: 'text.secondary' }}
                >
                    {title}
                </Typography>
            </Sheet>
        );
    }

    return (
        <Sheet
            variant="outlined"
            onDragOver={e => {
                e.preventDefault();
                // Over the column but not over any card: the end of the list.
                onDragOverAt(col.value, cards.length);
            }}
            onDrop={e => { e.preventDefault(); onDrop(col.value); }}
            sx={{
                width: 300, flexShrink: 0, borderRadius: 'sm', display: 'flex', flexDirection: 'column',
                minHeight: 0, maxHeight: '100%',
                borderTop: '3px solid', borderTopColor: sw.hex,
                background: isDropTarget
                    ? (dropRefused ? 'var(--joy-palette-danger-softBg)' : tint(sw.hex, 0.09))
                    : 'var(--joy-palette-background-level1)',
                transition: 'background 0.15s',
            }}
        >
            <Box sx={{ px: 1.25, py: 1, display: 'flex', alignItems: 'center', gap: 0.75, flexShrink: 0 }}>
                <Box sx={{ width: 8, height: 8, borderRadius: '50%', background: sw.hex, flexShrink: 0 }} />
                <Typography level="title-sm" noWrap sx={{ minWidth: 0 }} title={col.value || title}>
                    {title}
                </Typography>
                <Tooltip size="sm" title={col.limit > 0 ? `${cards.length} of at most ${col.limit}` : `${cards.length} cards`}>
                    <Chip
                        size="sm"
                        variant={over ? 'solid' : 'soft'}
                        color={over ? 'danger' : 'neutral'}
                        sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}
                    >
                        {col.limit > 0 ? `${cards.length}/${col.limit}` : cards.length}
                    </Chip>
                </Tooltip>
                <IconButton
                    size="sm" variant="plain" color="neutral" sx={{ ml: 'auto' }}
                    onClick={() => onCollapse(col.value, true)}
                >
                    <ChevronLeftIcon sx={{ fontSize: 16 }} />
                </IconButton>
            </Box>

            <Box sx={{ px: 1, pb: 1, overflowY: 'auto', overflowX: 'hidden', flex: 1, minHeight: 60 }}>
                {cards.length === 0 && (
                    <Box sx={{
                        border: '1px dashed', borderColor: 'divider', borderRadius: 'sm',
                        p: 2, textAlign: 'center',
                    }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {draggingHash ? 'Drop here' : 'Nothing here'}
                        </Typography>
                    </Box>
                )}
                {cards.map((c, i) => (
                    <React.Fragment key={c.Hash}>
                        {isDropTarget && dropIndex === i && !dropRefused && (
                            <Box sx={{ height: 3, borderRadius: 2, background: sw.hex, mb: 1, mt: -0.25 }} />
                        )}
                        <KanbanCardView
                            card={c}
                            board={board}
                            flipped={flipped.has(c.Hash)}
                            dim={terms.length > 0 && !cardMatches(c, terms)}
                            dragging={draggingHash === c.Hash}
                            clocked={clockedHash === c.Hash}
                            onFlip={() => onFlip(c.Hash)}
                            onDragStart={() => onDragStart(c)}
                            onDragEnd={onDragEnd}
                            onDragOverCard={e => {
                                e.preventDefault();
                                e.stopPropagation();
                                const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
                                onDragOverAt(col.value, e.clientY < r.top + r.height / 2 ? i : i + 1);
                            }}
                            onAct={onAct}
                        />
                    </React.Fragment>
                ))}
                {isDropTarget && dropIndex === cards.length && cards.length > 0 && !dropRefused && (
                    <Box sx={{ height: 3, borderRadius: 2, background: sw.hex, mb: 1 }} />
                )}
            </Box>
        </Sheet>
    );
}

