// The board
// ---------------------------------------------------------------------------

// Loaded lazily so that the dialog's weight is not on the path of opening a
// board, which is what every session starts with.
const KanbanSettings = React.lazy(() => import('./KanbanSettings'));

export default function Kanban() {
    const chrome = useChromeToggle();
    const [lastBoard, setLastBoard] = useSetting('kanbanBoard');

    const [boards, setBoards] = React.useState<KanbanBoard[]>([]);
    const [loadingBoards, setLoadingBoards] = React.useState(true);
    const [active, setActive] = React.useState<string>(lastBoard || '');
    const [stored, setStored] = React.useState<{ name: string; query: string }[]>([]);
    const [allTags, setAllTags] = React.useState<string[]>([]);

    const [cards, setCards] = React.useState<Card[]>([]);
    const [loadingCards, setLoadingCards] = React.useState(false);
    const [message, setMessage] = React.useState('');
    const [filter, setFilter] = React.useState('');
    const [flipped, setFlipped] = React.useState<Set<string>>(new Set());
    const [settingsOpen, setSettingsOpen] = React.useState(false);
    const [clockedHash, setClockedHash] = React.useState('');
    const [busy, setBusy] = React.useState(false);

    const [drag, setDrag] = React.useState<{ card: Card; from: string } | null>(null);
    const [dropAt, setDropAt] = React.useState<{ col: string; index: number } | null>(null);

    const board = React.useMemo(
        () => boards.find(b => b.name === active) || boards[0] || null,
        [boards, active],
    );

    // --- loading -----------------------------------------------------------

    const loadBoards = React.useCallback(async () => {
        setLoadingBoards(true);
        const [raw, sq, tags] = await Promise.all([
            ODb.getKanbanBoards(),
            ODb.getStoredQueries(),
            ODb.getAllTags(),
        ]);
        const list = (raw || []).map(normalizeBoard);
        setBoards(list);
        setStored(sq || []);
        setAllTags(tags || []);
        setActive(a => (list.some(b => b.name === a) ? a : (list.length > 0 ? list[0].name : '')));
        setLoadingBoards(false);
    }, []);

    React.useEffect(() => { loadBoards(); }, [loadBoards]);

    // Which board was open is remembered for this browser only.
    React.useEffect(() => {
        if (active && active !== lastBoard) setLastBoard(active);
    }, [active, lastBoard, setLastBoard]);

    const hasBoard = !!board;
    const queryKey = board ? `${board.storedQuery} ${board.query} ${board.includeArchived}` : '';

    const refresh = React.useCallback(async (signal?: AbortSignal) => {
        if (!board) { setCards([]); return; }
        const { query, baseFilter } = boardQuery(board, stored);
        setLoadingCards(true);
        const controller = signal ? null : new AbortController();
        const sig = signal || controller!.signal;
        try {
            const res = await ODb.query(query, false, sig, baseFilter);
            if (sig.aborted) return;
            setCards(Array.isArray(res) ? (res as Card[]) : []);
            setMessage('');
        } catch {
            if (!sig.aborted) { setCards([]); setMessage('Could not run that board’s query.'); }
        } finally {
            if (!sig.aborted) setLoadingCards(false);
        }
    }, [board, stored]);

    // The query is what decides the cards; the rest of a board's settings only
    // decide how they are drawn, so the cards are re-read when the query
    // changes and not when a colour does - which would otherwise be a round
    // trip per keystroke in the settings dialog. refresh is held in a ref and
    // kept out of the list for that same reason: it closes over the whole
    // board, colours and all.
    const refreshRef = React.useRef(refresh);
    refreshRef.current = refresh;
    React.useEffect(() => {
        if (!hasBoard) { setCards([]); return; }
        const controller = new AbortController();
        refreshRef.current(controller.signal);
        return () => controller.abort();
    }, [hasBoard, queryKey, stored]);

    // A drag that ends anywhere - on a column, on the gap between two of them,
    // outside the window entirely - puts the board back. Without this a drag
    // let go over nothing leaves the card it picked up faded and the board
    // waiting for a drop that is never coming.
    React.useEffect(() => {
        if (!drag) return;
        const done = () => { setDrag(null); setDropAt(null); };
        window.addEventListener('dragend', done);
        window.addEventListener('drop', done);
        return () => {
            window.removeEventListener('dragend', done);
            window.removeEventListener('drop', done);
        };
    }, [drag]);

    // The heading the clock is running on, so a card can offer to stop it.
    const readClock = React.useCallback(async () => {
        try {
            const st: any = await ODb.getClockState();
            setClockedHash(st && st.Active && st.Target ? (st.Target.Hash || '') : '');
        } catch { /* a server with no clock running is not an error worth showing */ }
    }, []);
    React.useEffect(() => { readClock(); }, [readClock]);

    // --- board writes ------------------------------------------------------

    const saveBoards = React.useCallback(async (next: KanbanBoard[]) => {
        setBoards(next);
        const res = await ODb.saveKanbanBoards(next);
        if (res && res.Ok === false) setMessage(res.Msg || 'Could not save the boards.');
    }, []);

    function addBoard() {
        const name = uniqueName('Board', boards.map(b => b.name));
        const b = newBoard(name);
        const next = [...boards, b];
        saveBoards(next);
        setActive(name);
        setSettingsOpen(true);
    }

    function onSaveBoard(next: KanbanBoard, originalName: string) {
        const list = boards.map(b => (b.name === originalName ? next : b));
        saveBoards(list);
        setActive(next.name);
        setSettingsOpen(false);
    }

    function onDeleteBoard(name: string) {
        const list = boards.filter(b => b.name !== name);
        saveBoards(list);
        setActive(list.length > 0 ? list[0].name : '');
        setSettingsOpen(false);
    }

    function onDuplicateBoard(b: KanbanBoard) {
        const name = uniqueName(`${b.name} copy`, boards.map(x => x.name));
        const copy = { ...b, name };
        saveBoards([...boards, copy]);
        setActive(name);
        setSettingsOpen(false);
    }

    // A column folded away is part of the board rather than of this page: a
    // Done column you folded last week should still be folded today.
    const setCollapsed = React.useCallback((value: string, collapsed: boolean) => {
        if (!board) return;
        if (value === UNSET) return; // the catch-all is not stored, so it cannot remember
        const next = boards.map(b => (b.name !== board.name ? b : {
            ...b,
            columns: b.columns.map(c => (c.value === value ? { ...c, collapsed } : c)),
        }));
        saveBoards(next);
    }, [board, boards, saveBoards]);

    const collapseAll = React.useCallback((collapsed: boolean) => {
        if (!board) return;
        const next = boards.map(b => (b.name !== board.name ? b : {
            ...b, columns: b.columns.map(c => ({ ...c, collapsed })),
        }));
        saveBoards(next);
    }, [board, boards, saveBoards]);

    function fillColumnsFromCards() {
        if (!board) return;
        const found = discoverValues(cards, board);
        if (found.length === 0) return;
        const next = boards.map(b => (b.name !== board.name ? b : {
            ...b,
            columns: [...b.columns, ...found.map(v => ({ value: v, title: '', color: '', limit: 0, collapsed: false }))],
        }));
        saveBoards(next);
    }

    // --- layout ------------------------------------------------------------

    const terms = React.useMemo(() => searchTerms(filter), [filter]);

    // Every column of the board plus, when it is asked for, the one that
    // catches whatever no column claimed. That last one is appended rather than
    // stored, so turning it off and on again cannot lose a configured column.
    const columns: KanbanColumn[] = React.useMemo(() => {
        if (!board) return [];
        const cols = board.columns.slice();
        if (board.showUnset) cols.push(unsetColumn(board));
        return cols;
    }, [board]);

    const buckets = React.useMemo(() => {
        const out = new Map<string, Card[]>();
        if (!board) return out;
        for (const col of columns) out.set(col.value, []);
        for (const c of cards) {
            const value = columnOf(c, board);
            const list = out.get(value);
            if (list) list.push(c);
        }
        const sorted = new Map<string, Card[]>();
        out.forEach((list, key) => sorted.set(key, sortCards(list, board)));
        return sorted;
    }, [cards, columns, board]);

    // Cards the query found that no column on the board wanted. Worth saying
    // out loud: a board quietly showing two thirds of its query looks like a
    // board with fewer cards on it, not like a board missing a column.
    const homeless = React.useMemo(() => {
        if (!board) return 0;
        let n = 0;
        const have = new Set(columns.map(c => c.value));
        for (const c of cards) if (!have.has(columnOf(c, board))) n++;
        return n;
    }, [cards, columns, board]);

    const matched = React.useMemo(
        () => (terms.length === 0 ? cards.length : cards.filter(c => cardMatches(c, terms)).length),
        [cards, terms],
    );

    // Dropping into the catch-all column means taking the value away, and there
    // is one case where that cannot be done: org has no way to spell a heading
    // with no todo keyword through this endpoint, so the board refuses the drop
    // rather than writing something the server will reject.
    const dropRefusedFor = React.useCallback((value: string): boolean => {
        return !!board && board.groupBy === 'status' && value === UNSET;
    }, [board]);

    // --- moving a card -----------------------------------------------------

    // The order value the moved card needs to land where it was dropped, and
    // the renumbering to fall back on when the gap it was dropped into has run
    // out of room. Only the card that moved is written in the ordinary case.
    function planOrder(target: string, index: number, moving: Card): { writes: { card: Card; value: number }[] } | null {
        if (!board || board.sort !== 'manual') return null;
        const list = (buckets.get(target) || []).filter(c => c.Hash !== moving.Hash);
        const at = Math.max(0, Math.min(index, list.length));
        const prev = at > 0 ? list[at - 1] : null;
        const next = at < list.length ? list[at] : null;
        const prevOrder = prev ? orderOf(prev, board) : null;
        const nextOrder = next ? orderOf(next, board) : null;

        // A card sitting above the drop with no order of its own has nothing to
        // be above: the whole column is renumbered rather than guessed at.
        if (!(prev && prevOrder === null)) {
            const value = orderBetween(prevOrder, nextOrder);
            if (value !== null) return { writes: [{ card: moving, value }] };
        }
        const after = list.slice();
        after.splice(at, 0, moving);
        const numbers = renumber(after.length);
        const writes: { card: Card; value: number }[] = [];
        after.forEach((c, i) => {
            if (c.Hash === moving.Hash || orderOf(c, board) !== numbers[i]) writes.push({ card: c, value: numbers[i] });
        });
        return { writes };
    }

    async function moveCard(card: Card, from: string, target: string, index: number) {
        if (!board) return;
        if (dropRefusedFor(target)) {
            setMessage('A heading cannot have its todo keyword taken away from here.');
            return;
        }
        setBusy(true);
        setMessage('');

        const order = planOrder(target, index, card);

        // The board moves the card at once and asks afterwards. A write that
        // fails puts the message up and refreshes, which reads the truth back
        // off the server rather than leaving a card somewhere it is not.
        const optimistic = (c: Card): Card => {
            if (c.Hash !== card.Hash) return c;
            const next: Card = { ...c, Props: { ...(c.Props || {}) }, Tags: (c.Tags || []).slice() };
            if (from !== target) {
                if (board.groupBy === 'property') next.Props![board.groupKey] = target;
                else if (board.groupBy === 'status') next.Status = target;
                else if (board.groupBy === 'tag') {
                    next.Tags = next.Tags!.filter(t => t !== from);
                    if (target !== UNSET) next.Tags!.push(target);
                }
            }
            return next;
        };
        setCards(cs => cs.map(c => {
            let out = optimistic(c);
            if (order) {
                const w = order.writes.find(x => x.card.Hash === c.Hash);
                if (w) out = { ...out, Props: { ...(out.Props || {}), [board.orderKey || 'KANBAN']: formatOrder(w.value) } };
            }
            return out;
        }));

        let failed = '';
        try {
            if (from !== target) {
                if (board.groupBy === 'property') {
                    const res: any = await ODb.changeProperty(card.Hash, board.groupKey, target);
                    if (res && res.Ok === false) failed = `Could not set ${board.groupKey}.`;
                } else if (board.groupBy === 'status') {
                    const res: any = await ODb.changeStatus(card.Hash, target);
                    if (!res || res.Ok === false) failed = `${target} is not a todo keyword that file allows.`;
                } else if (board.groupBy === 'tag') {
                    if (from !== UNSET) await ODb.toggleTag(card.Hash, from);
                    if (target !== UNSET) await ODb.toggleTag(card.Hash, target);
                }
            }
            if (!failed && order) {
                const key = board.orderKey || 'KANBAN';
                for (const w of order.writes) {
                    await ODb.changeProperty(w.card.Hash, key, formatOrder(w.value));
                }
            }
        } catch {
            failed = 'The server did not take that move.';
        }

        if (failed) setMessage(failed);
        setBusy(false);
        // Either way the board reads itself back: the hash of a heading whose
        // keyword changed is not the hash it had, and a stale one cannot be
        // dragged again.
        refresh();
    }

    async function onAct(what: 'archive' | 'clockin' | 'clockout', card: Card) {
        setBusy(true);
        try {
            if (what === 'archive') await ODb.archiveEntry(card.Hash);
            else if (what === 'clockin') { await ODb.clockIn(card.Hash); setClockedHash(card.Hash); }
            else { await ODb.clockOut(); setClockedHash(''); }
        } catch {
            setMessage('That did not go through.');
        }
        setBusy(false);
        if (what === 'archive') refresh();
        else readClock();
    }

    function toggleFlip(hash: string) {
        setFlipped(f => {
            const next = new Set(f);
            if (next.has(hash)) next.delete(hash); else next.add(hash);
            return next;
        });
    }

    // --- render ------------------------------------------------------------

    if (loadingBoards) {
        return <Box sx={{ display: 'flex', justifyContent: 'center', p: 6 }}><CircularProgress /></Box>;
    }

    if (boards.length === 0) {
        return (
            <Sheet variant="soft" sx={{ borderRadius: 'md', p: 6, textAlign: 'center', maxWidth: 560, mx: 'auto', mt: 4 }}>
                <ViewKanbanIcon sx={{ fontSize: 44, color: 'text.tertiary' }} />
                <Typography level="title-lg" sx={{ mt: 1 }}>No boards yet</Typography>
                <Typography level="body-sm" sx={{ color: 'text.secondary', mt: 0.5, mb: 2 }}>
                    A board takes a saved query and lays its headings out in columns, split by a
                    property, a tag or the todo keyword. It writes nothing into your files until
                    you drag a card.
                </Typography>
                <Button startDecorator={<AddIcon />} onClick={addBoard}>New board</Button>
            </Sheet>
        );
    }

    const allCollapsed = board ? columns.length > 0 && columns.every(c => c.collapsed) : false;

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, gap: 1 }}>
            {/* Boards */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
                <Tabs
                    size="sm"
                    value={active}
                    onChange={(_, v) => setActive((v as string) || '')}
                    sx={{ bgcolor: 'transparent', minWidth: 0, flex: 1 }}
                >
                    <TabList
                        variant="plain"
                        sx={{
                            '--List-gap': '4px', flexWrap: 'nowrap', overflowX: 'auto', minWidth: 0,
                            '&::-webkit-scrollbar': { height: 4 },
                        }}
                    >
                        {boards.map(b => (
                            <Tab key={b.name} value={b.name} sx={{ flex: 'none', borderRadius: 'sm' }}>
                                {b.name}
                            </Tab>
                        ))}
                    </TabList>
                </Tabs>
                <Tooltip size="sm" title="New board">
                    <IconButton size="sm" variant="soft" onClick={addBoard}><AddIcon fontSize="small" /></IconButton>
                </Tooltip>
            </Box>

            {/* Tools */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <Input
                    size="sm"
                    placeholder="Find a card"
                    value={filter}
                    onChange={e => setFilter(e.target.value)}
                    startDecorator={<SearchIcon fontSize="small" />}
                    sx={{ width: 240 }}
                />
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {terms.length > 0 ? `${matched} of ${cards.length}` : `${cards.length} card${cards.length === 1 ? '' : 's'}`}
                    {board && board.storedQuery ? ` · ${board.storedQuery}` : ''}
                </Typography>
                {(loadingCards || busy) && <CircularProgress size="sm" />}

                <Box sx={{ ml: 'auto', display: 'flex', gap: 0.5 }}>
                    {flipped.size > 0 && (
                        <Tooltip size="sm" title="Turn every card back over">
                            <IconButton size="sm" variant="plain" onClick={() => setFlipped(new Set())}>
                                <FlipIcon fontSize="small" />
                            </IconButton>
                        </Tooltip>
                    )}
                    <Tooltip size="sm" title={allCollapsed ? 'Open every column' : 'Fold every column'}>
                        <IconButton size="sm" variant="plain" onClick={() => collapseAll(!allCollapsed)}>
                            {allCollapsed ? <UnfoldMoreIcon fontSize="small" /> : <UnfoldLessIcon fontSize="small" />}
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="Run the query again">
                        <IconButton size="sm" variant="plain" onClick={() => refresh()}><RefreshIcon fontSize="small" /></IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="Board settings">
                        <IconButton size="sm" variant="plain" onClick={() => setSettingsOpen(true)}><SettingsIcon fontSize="small" /></IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title={chrome.hidden ? 'Show the title again' : 'Give the board the window'}>
                        <IconButton size="sm" variant="plain" onClick={() => chrome.setHidden(!chrome.hidden)}>
                            {chrome.hidden ? <CloseFullscreenIcon fontSize="small" /> : <OpenInFullIcon fontSize="small" />}
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>

            {message && (
                <Alert size="sm" variant="soft" color="warning" endDecorator={
                    <Button size="sm" variant="plain" color="neutral" onClick={() => setMessage('')}>Dismiss</Button>
                }>
                    {message}
                </Alert>
            )}

            {board && board.columns.length === 0 && (
                <Alert
                    size="sm"
                    variant="soft"
                    color="primary"
                    endDecorator={
                        <Box sx={{ display: 'flex', gap: 1 }}>
                            <Button size="sm" variant="soft" startDecorator={<AutoAwesomeIcon />} onClick={fillColumnsFromCards}>
                                Fill from the cards
                            </Button>
                            <Button size="sm" variant="plain" onClick={() => setSettingsOpen(true)}>Settings</Button>
                        </Box>
                    }
                >
                    This board has no columns. It can read them off whatever the query found.
                </Alert>
            )}

            {homeless > 0 && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {homeless} card{homeless === 1 ? '' : 's'} no column claims
                    {board && !board.showUnset ? ' — turn on the catch-all column in settings to see them.' : '.'}
                </Typography>
            )}

            {/* The board */}
            <Box
                sx={{
                    display: 'flex', gap: 1.25, flex: 1, minHeight: 0, overflowX: 'auto', overflowY: 'hidden',
                    pb: 1, alignItems: 'stretch',
                }}
                onDragLeave={e => { if (e.currentTarget === e.target) setDropAt(null); }}
            >
                {board && columns.map(col => (
                    <Column
                        key={col.value || ' unset'}
                        col={col}
                        cards={buckets.get(col.value) || []}
                        board={board}
                        flipped={flipped}
                        terms={terms}
                        dropIndex={dropAt && dropAt.col === col.value ? dropAt.index : null}
                        isDropTarget={!!drag && !!dropAt && dropAt.col === col.value}
                        dropRefused={dropRefusedFor(col.value)}
                        draggingHash={drag ? drag.card.Hash : null}
                        clockedHash={clockedHash}
                        onFlip={toggleFlip}
                        onCollapse={setCollapsed}
                        onDragStart={c => setDrag({ card: c, from: columnOf(c, board) })}
                        onDragEnd={() => { setDrag(null); setDropAt(null); }}
                        onDragOverAt={(value, index) => setDropAt({ col: value, index })}
                        onDrop={value => {
                            const d = drag;
                            const at = dropAt && dropAt.col === value ? dropAt.index : (buckets.get(value) || []).length;
                            setDrag(null);
                            setDropAt(null);
                            if (d) moveCard(d.card, d.from, value, at);
                        }}
                        onAct={onAct}
                    />
                ))}
                {board && columns.length === 0 && (
                    <Box sx={{ p: 4, color: 'text.tertiary' }}>
                        <Typography level="body-sm">Nothing to show until this board has a column.</Typography>
                    </Box>
                )}
            </Box>

            {board && settingsOpen && (
                <React.Suspense fallback={null}>
                    <KanbanSettings
                        open={settingsOpen}
                        board={board}
                        boards={boards}
                        stored={stored}
                        cards={cards}
                        allTags={allTags}
                        onClose={() => setSettingsOpen(false)}
                        onSave={onSaveBoard}
                        onDelete={onDeleteBoard}
                        onDuplicate={onDuplicateBoard}
                    />
                </React.Suspense>
            )}
        </Box>
    );
}
