// The raw org file, coloured the way an editor would colour it.
//
// This is a highlighter rather than a parser: it walks the file a line at a
// time, decides what kind of line it is looking at, and splits that line into
// spans. Nothing here builds a tree, because nothing downstream needs one - the
// file view only wants the text back with colour on it.
//
// The two things that do carry across lines are blocks (#+BEGIN_SRC ... #+END)
// and drawers (:PROPERTIES: ... :END:), both of which change how the lines
// inside them are read, so the walk keeps that much state.

import * as React from 'react';
import Box from '@mui/joy/Box';
import { useColorScheme } from '@mui/joy/styles';

// ---------------------------------------------------------------------------
// Todo keywords
// ---------------------------------------------------------------------------

// What the server hands out when a file says nothing, from defaultTodoStates in
// settings.go. A file's own #+TODO:/#+SEQ_TODO:/#+TYP_TODO: line replaces it,
// which is why the keywords are read off the text rather than fixed here.
const DEFAULT_TODO_STATES = 'TODO INPROGRESS IN-PROGRESS NEXT BLOCKED PAUSED WAITING PHONE MEETING BACKLOG | DONE CANCELLED';

export type TodoStates = { active: Set<string>; done: Set<string> };

// "TODO NEXT | DONE CANCELLED" - everything after the bar is a finished state,
// and with no bar the last word is the finished one, as org itself has it.
function parseTodoStates(spec: string): { active: string[]; done: string[] } {
    const words = spec
        .split(/\s+/)
        .map(w => w.replace(/\([^)]*\)$/, '')) // TODO(t) - the key is not part of the name
        .filter(w => w !== '');
    const bar = words.indexOf('|');
    if (bar >= 0) return { active: words.slice(0, bar), done: words.slice(bar + 1) };
    if (words.length === 0) return { active: [], done: [] };
    return { active: words.slice(0, -1), done: words.slice(-1) };
}

// The keywords this file uses: the defaults, plus anything its own #+TODO lines
// declare. They add rather than replace so that a file declaring one extra
// sequence does not lose the states the server would still accept.
export function todoStates(text: string): TodoStates {
    const active = new Set<string>();
    const done = new Set<string>();
    const add = (spec: string) => {
        const p = parseTodoStates(spec);
        p.active.forEach(w => active.add(w));
        p.done.forEach(w => done.add(w));
    };
    add(DEFAULT_TODO_STATES);
    const re = /^#\+(?:TODO|SEQ_TODO|TYP_TODO):(.*)$/gim;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text)) !== null) add(m[1]);
    // A state named on both sides of two different sequences is finished: the
    // heading is done, whatever else some other sequence calls it.
    done.forEach(w => active.delete(w));
    return { active, done };
}

