// A quick look at the numbers in a spreadsheet selection, as a line chart in a
// popup over the grid. The drawing is plain svg - the shapes it needs (a dotted
// smooth line, a dot per reading and a wash of colour underneath) are a few
// lines of path maths, and that is cheaper than carrying a chart library.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Chip from '@mui/joy/Chip';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Typography from '@mui/joy/Typography';
import Tooltip from '@mui/joy/Tooltip';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import Button from '@mui/joy/Button';
import TableRowsIcon from '@mui/icons-material/TableRows';
import ViewColumnIcon from '@mui/icons-material/ViewColumn';

export type ChartSeries = { name: string; points: (number | null)[] };
export type ChartSet = { labels: string[]; series: ChartSeries[] };

// The same selection read both ways round: one series per selected row, or one
// series per selected column. Which one the numbers want depends on how the
// table is laid out, so the reader gets to flip it.
export type ChartInput = { byRow: ChartSet; byCol: ChartSet; prefer: 'byRow' | 'byCol' };

export type CellChartProps = {
    open: boolean;
    onClose: () => void;
    series: ChartInput;
    title: string;
};

const SERIES_COLORS = ['#8b5cf6', '#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#06b6d4', '#ec4899', '#84cc16'];

const PAD = { top: 18, right: 24, bottom: 46, left: 60 };
const VIEW = { w: 960, h: 420 };

type Pt = { x: number; y: number; i: number; v: number };

// Catmull-Rom through every point, written out as the cubic beziers svg wants,
// so the line curves through its readings instead of cornering at them.
function smoothPath(pts: Pt[], top: number, bottom: number): string {
    if (pts.length === 0) return '';
    if (pts.length === 1) return `M ${pts[0].x} ${pts[0].y}`;
    const clampY = (y: number) => Math.min(Math.max(y, top), bottom);
    let d = `M ${pts[0].x} ${pts[0].y}`;
    for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i - 1] || pts[i];
        const p1 = pts[i];
        const p2 = pts[i + 1];
        const p3 = pts[i + 2] || p2;
        const c1x = p1.x + (p2.x - p0.x) / 6;
        const c1y = clampY(p1.y + (p2.y - p0.y) / 6);
        const c2x = p2.x - (p3.x - p1.x) / 6;
        const c2y = clampY(p2.y - (p3.y - p1.y) / 6);
        d += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
    }
    return d;
}

// Gaps in the data break the line rather than being drawn across.
function runs(pts: (Pt | null)[]): Pt[][] {
    const out: Pt[][] = [];
    let cur: Pt[] = [];
    for (const p of pts) {
        if (p === null) {
            if (cur.length > 0) out.push(cur);
            cur = [];
        } else {
            cur.push(p);
        }
    }
    if (cur.length > 0) out.push(cur);
    return out;
}

// Round numbers for the value axis, at roughly the count asked for.
function ticks(lo: number, hi: number, count: number): number[] {
    const span = hi - lo;
    if (span <= 0) return [lo];
    const rough = span / count;
    const mag = Math.pow(10, Math.floor(Math.log10(rough)));
    const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= rough) || mag * 10;
    const out: number[] = [];
    for (let v = Math.ceil(lo / step) * step; v <= hi + step / 1000; v += step) out.push(Number(v.toFixed(10)));
    return out;
}

function format(v: number): string {
    if (v === 0) return '0';
    const a = Math.abs(v);
    if (a >= 1e6 || a < 1e-3) return v.toExponential(1);
    return String(Number(v.toFixed(a < 1 ? 4 : 2)));
}

export default function CellChart(props: CellChartProps) {
    const [orient, setOrient] = React.useState<'byRow' | 'byCol'>(props.series.prefer);
    const [hidden, setHidden] = React.useState<Record<number, boolean>>({});

    // A fresh selection starts over, both in how it is read and in what is shown.
    React.useEffect(() => {
        if (props.open) {
            setOrient(props.series.prefer);
            setHidden({});
        }
    }, [props.open, props.series]);

    const set = orient === 'byRow' ? props.series.byRow : props.series.byCol;
    const shown = set.series.map((s, i) => ({ s, i })).filter(({ i }) => !hidden[i]);

    let lo = Number.POSITIVE_INFINITY;
    let hi = Number.NEGATIVE_INFINITY;
    for (const { s } of shown) {
        for (const v of s.points) {
            if (v === null) continue;
            lo = Math.min(lo, v);
            hi = Math.max(hi, v);
        }
    }
    const empty = lo > hi;
    if (empty) {
        lo = 0;
        hi = 1;
    } else if (lo === hi) {
        const pad = Math.abs(lo) > 0 ? Math.abs(lo) * 0.1 : 1;
        lo -= pad;
        hi += pad;
    } else {
        const pad = (hi - lo) * 0.08;
        lo -= pad;
        hi += pad;
    }

    const plot = {
        left: PAD.left,
        right: VIEW.w - PAD.right,
        top: PAD.top,
        bottom: VIEW.h - PAD.bottom,
    };
    const n = set.labels.length;
    const xOf = (i: number) => (n <= 1 ? (plot.left + plot.right) / 2 : plot.left + ((plot.right - plot.left) * i) / (n - 1));
    const yOf = (v: number) => plot.bottom - ((v - lo) / (hi - lo)) * (plot.bottom - plot.top);

    const yTicks = ticks(lo, hi, 5);
    const labelStride = n <= 14 ? 1 : Math.ceil(n / 14);

    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog
                variant="outlined"
                layout="center"
                sx={{
                    width: 'min(1040px, 94vw)',
                    maxHeight: '92vh',
                    p: 2,
                    gap: 1.5,
                    borderRadius: 'lg',
                    boxShadow: 'lg',
                    backgroundImage:
                        'linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0) 40%, rgba(0,0,0,0.035)), linear-gradient(180deg, var(--joy-palette-background-surface), var(--joy-palette-background-level1))',
                }}
            >
                <ModalClose />
                <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 2, pr: 4 }}>
                    <Box sx={{ minWidth: 0 }}>
                        <Typography level="title-md" sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {props.title}
                        </Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {shown.length} of {set.series.length} series &times; {n} points
                        </Typography>
                    </Box>
                    <Box sx={{ flex: 1 }} />
                    <ToggleButtonGroup
                        size="sm"
                        value={orient}
                        onChange={(_, v) => { if (v) setOrient(v as 'byRow' | 'byCol'); }}
                        sx={{ '--ButtonGroup-radius': '8px', backgroundImage: 'linear-gradient(180deg, rgba(255,255,255,0.10), rgba(0,0,0,0.03))' }}
                    >
                        <Tooltip title="One line per selected row" size="sm">
                            <Button value="byRow" startDecorator={<TableRowsIcon />}>Rows</Button>
                        </Tooltip>
                        <Tooltip title="One line per selected column" size="sm">
                            <Button value="byCol" startDecorator={<ViewColumnIcon />}>Columns</Button>
                        </Tooltip>
                    </ToggleButtonGroup>
                </Box>

                <Box
                    sx={{
                        borderRadius: 'md',
                        border: '1px solid',
                        borderColor: 'divider',
                        overflow: 'hidden',
                        backgroundImage: 'linear-gradient(180deg, var(--joy-palette-background-surface), var(--joy-palette-background-level1))',
                    }}
                >
                    <svg viewBox={`0 0 ${VIEW.w} ${VIEW.h}`} style={{ display: 'block', width: '100%', height: 'auto' }}>
                        <defs>
                            {SERIES_COLORS.map((c, i) => (
                                <linearGradient key={i} id={`cellchart-fill-${i}`} x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="0%" stopColor={c} stopOpacity="0.28" />
                                    <stop offset="55%" stopColor={c} stopOpacity="0.09" />
                                    <stop offset="100%" stopColor={c} stopOpacity="0" />
                                </linearGradient>
                            ))}
                        </defs>

                        {/* Value axis: dotted rules, so the lines stay the loudest thing here */}
                        {yTicks.map((t, i) => (
                            <g key={i}>
                                <line
                                    x1={plot.left}
                                    x2={plot.right}
                                    y1={yOf(t)}
                                    y2={yOf(t)}
                                    stroke="var(--joy-palette-neutral-outlinedBorder)"
                                    strokeWidth="1"
                                    strokeDasharray="2 5"
                                />
                                <text
                                    x={plot.left - 10}
                                    y={yOf(t) + 4}
                                    textAnchor="end"
                                    fontSize="12"
                                    fontFamily="var(--joy-fontFamily-code, monospace)"
                                    fill="var(--joy-palette-text-tertiary)"
                                >
                                    {format(t)}
                                </text>
                            </g>
                        ))}

                        {set.labels.map((label, i) =>
                            i % labelStride === 0 ? (
                                <text
                                    key={i}
                                    x={xOf(i)}
                                    y={plot.bottom + 22}
                                    textAnchor="middle"
                                    fontSize="12"
                                    fontFamily="var(--joy-fontFamily-code, monospace)"
                                    fill="var(--joy-palette-text-tertiary)"
                                >
                                    {label.length > 14 ? label.slice(0, 13) + '…' : label}
                                </text>
                            ) : null,
                        )}

                        <line
                            x1={plot.left}
                            x2={plot.right}
                            y1={plot.bottom}
                            y2={plot.bottom}
                            stroke="var(--joy-palette-neutral-outlinedBorder)"
                            strokeWidth="1"
                        />

                        {shown.map(({ s, i }) => {
                            const color = SERIES_COLORS[i % SERIES_COLORS.length];
                            const pts: (Pt | null)[] = s.points.map((v, j) =>
                                v === null ? null : { x: xOf(j), y: yOf(v), i: j, v },
                            );
                            const segments = runs(pts);
                            return (
                                <g key={i}>
                                    {segments.map((seg, k) => {
                                        const line = smoothPath(seg, plot.top, plot.bottom);
                                        const area = `${line} L ${seg[seg.length - 1].x} ${plot.bottom} L ${seg[0].x} ${plot.bottom} Z`;
                                        return (
                                            <g key={k}>
                                                <path d={area} fill={`url(#cellchart-fill-${i % SERIES_COLORS.length})`} stroke="none" />
                                                <path
                                                    d={line}
                                                    fill="none"
                                                    stroke={color}
                                                    strokeWidth="2.25"
                                                    strokeDasharray="1 6"
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                />
                                            </g>
                                        );
                                    })}
                                    {segments.flat().map(p => (
                                        <circle
                                            key={p.i}
                                            cx={p.x}
                                            cy={p.y}
                                            r="3.6"
                                            fill="var(--joy-palette-background-surface)"
                                            stroke={color}
                                            strokeWidth="2"
                                        >
                                            <title>{`${s.name} · ${set.labels[p.i]}: ${format(p.v)}`}</title>
                                        </circle>
                                    ))}
                                </g>
                            );
                        })}

                        {empty && (
                            <text
                                x={(plot.left + plot.right) / 2}
                                y={(plot.top + plot.bottom) / 2}
                                textAnchor="middle"
                                fontSize="14"
                                fill="var(--joy-palette-text-tertiary)"
                            >
                                Nothing numeric in this selection
                            </text>
                        )}
                    </svg>
                </Box>

                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
                    {set.series.map((s, i) => {
                        const color = SERIES_COLORS[i % SERIES_COLORS.length];
                        const off = hidden[i] === true;
                        return (
                            <Chip
                                key={i}
                                size="sm"
                                variant="outlined"
                                onClick={() => setHidden(h => ({ ...h, [i]: !off }))}
                                sx={{
                                    borderRadius: '7px',
                                    opacity: off ? 0.45 : 1,
                                    backgroundImage: 'linear-gradient(180deg, rgba(255,255,255,0.08), rgba(0,0,0,0.02))',
                                }}
                                startDecorator={
                                    <Box
                                        sx={{
                                            width: 9,
                                            height: 9,
                                            borderRadius: '50%',
                                            backgroundColor: off ? 'transparent' : color,
                                            boxShadow: `inset 0 0 0 2px ${color}`,
                                        }}
                                    />
                                }
                            >
                                {s.name}
                            </Chip>
                        );
                    })}
                    <Box sx={{ flex: 1 }} />
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        Click a name to hide its line · Esc closes
                    </Typography>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
